import type { Chunk } from '../world/chunk';
import { TerrainGenerator } from './terrain';
import { StubMapGenerator } from './stubMap';
import { MapGenerator, getMapcore } from './mapGenerator';

/**
 * Which generator a world uses (saved in its meta):
 * - `terrain`: the infinite noise terrain from the seed (every world before map worlds);
 * - `map`: a real place converted from OpenStreetMap (MAP_WORLDS.md) by mapcore (`MapGenerator`);
 *   map worlds without a MapPackage (the test area from phase A) use the TS `StubMapGenerator`.
 */
export type GeneratorKind = 'terrain' | 'map';

export const GENERATOR_KINDS: readonly GeneratorKind[] = ['terrain', 'map'];

/** Anything that is not a known kind (old saves have none) means `terrain`. */
export function normalizeGeneratorKind(kind: unknown): GeneratorKind {
  return kind === 'map' ? 'map' : 'terrain';
}

/** Geographic bounds of a map world, degrees: [south, west, north, east] (Overpass order). */
export type GeoBBox = [number, number, number, number];

/** The part of a world's meta that decides how its chunks are generated. */
export interface GeneratorSpec {
  /** Absent (old saves) means `terrain`. */
  generator?: GeneratorKind;
  seed: number;
  /** Map worlds: key of the stored MapPackage (absent for the stub). */
  mapPackageId?: string;
}

/** What the game, the gen workers and the server need from a world generator. */
export interface ChunkGenerator {
  readonly kind: GeneratorKind;
  readonly seed: number;
  /** Deterministic: the same (spec, cx, cz) gives the same blocks in every thread and process. */
  generateChunk(cx: number, cz: number): Chunk;
  /** Height of the top block of a world column (F3 overlay, title camera). */
  surfaceHeight(wx: number, wz: number): number;
  /** A biome (or area) name for the F3 overlay. */
  biomeAt?(wx: number, wz: number): string;
  /** Preferred spawn [x, y, z] (block coordinates); absent means the world origin. */
  spawn?(): { x: number; y: number; z: number };
  /** Frees native resources (mapcore's WASM memory). */
  dispose?(): void;
}

class TerrainChunkGenerator implements ChunkGenerator {
  readonly kind = 'terrain' as const;
  readonly terrain: TerrainGenerator;
  constructor(seed: number) {
    this.terrain = new TerrainGenerator(seed);
  }
  get seed(): number {
    return this.terrain.seed;
  }
  generateChunk(cx: number, cz: number): Chunk {
    return this.terrain.generateChunk(cx, cz);
  }
  surfaceHeight(wx: number, wz: number): number {
    return this.terrain.surfaceHeight(wx, wz);
  }
  biomeAt(wx: number, wz: number): string {
    return this.terrain.biomeAt(wx, wz);
  }
}

/**
 * Creates the generator for a world. A map world with a `mapPackageId` needs its MapPackage bytes
 * (`mapPackage`) and a registered mapcore (`registerMapcore`); a map world without one is the stub
 * test area.
 */
export function createGenerator(spec: GeneratorSpec, mapPackage?: Uint8Array): ChunkGenerator {
  const kind = normalizeGeneratorKind(spec.generator);
  if (kind === 'map') {
    if (mapPackage) return new MapGenerator(getMapcore(), mapPackage, spec.seed >>> 0);
    if (spec.mapPackageId !== undefined) throw new Error(`Map package ${spec.mapPackageId} was not loaded`);
    return new StubMapGenerator(spec.seed >>> 0);
  }
  return new TerrainChunkGenerator(spec.seed);
}

/** A cache key: two specs with the same key generate identical chunks. */
export function generatorKey(spec: GeneratorSpec): string {
  const kind = normalizeGeneratorKind(spec.generator);
  return kind === 'map' ? `map:${spec.mapPackageId ?? 'stub'}` : `terrain:${spec.seed >>> 0}`;
}

/** Spawn column centre for a generator: its preferred spawn, else the origin. */
export function spawnColumn(gen: ChunkGenerator): { x: number; z: number } {
  const s = gen.spawn?.();
  return s ? { x: Math.floor(s.x) + 0.5, z: Math.floor(s.z) + 0.5 } : { x: 0.5, z: 0.5 };
}
