/**
 * Sky light and block light (Milestone 5).
 *
 * Both are 0..15 levels stored as nibbles in `Chunk.light` (sky in the high nibble, block light in
 * the low one). Light spreads by flood fill: a neighbour gets `level - 1 - filter(neighbour)`, where
 * the filter is 0 for clear cells, small for leaves/water and "everything" for opaque blocks. Sky
 * light has one extra rule: level 15 moving straight down into a clear cell stays 15, so open sky
 * fills vertical shafts without falloff.
 *
 * How the world stays correct:
 *
 * 1. `computeChunkLight` (run in the gen worker) lights a freshly generated chunk on its own: a
 *    column pass marks every cell with open sky above it as 15, then a BFS spreads sky light from
 *    the cells that border darker columns, and a second BFS spreads block light from emitters.
 *    Light never crosses the chunk edge here.
 * 2. `LightEngine.stitchChunk` (main thread, right after the chunk is added to the World and so
 *    before it can be meshed) seeds an "increase" BFS from every border cell on either side of
 *    each loaded neighbour where one side can brighten the other, and lets it spread through all
 *    loaded chunks. Light is the max over all sources of (source - path cost), so per-chunk results
 *    are lower bounds and spreading across the borders reaches the exact fixpoint. Every section
 *    whose light changes is marked dirty (including diagonal neighbours, since smooth lighting
 *    samples them), so already meshed neighbours re-mesh.
 * 3. `LightEngine.onBlockChanged` handles edits with the standard removal + increase queues.
 */
import { BLOCK_LIGHT_EMISSION, BLOCK_LIGHT_FILTER, MAX_LIGHT } from './blocks';
import { CHUNK_HEIGHT, CHUNK_VOLUME, MAX_Y, MIN_Y, SECTION_COUNT, sectionOf, type Chunk } from './chunk';
import { decodeSectionKey, sectionKey, type World } from './world';

/** Growable FIFO ring buffer of int32 values. */
export class IntQueue {
  private buf: Int32Array;
  private mask: number;
  private head = 0;
  private tail = 0;

  constructor(capacityPow2 = 1 << 12) {
    this.buf = new Int32Array(capacityPow2);
    this.mask = capacityPow2 - 1;
  }

  get size(): number {
    return (this.tail - this.head) & this.mask;
  }

  get isEmpty(): boolean {
    return this.head === this.tail;
  }

  push(v: number): void {
    this.buf[this.tail] = v;
    this.tail = (this.tail + 1) & this.mask;
    if (this.tail === this.head) this.grow();
  }

  shift(): number {
    const v = this.buf[this.head]!;
    this.head = (this.head + 1) & this.mask;
    return v;
  }

  clear(): void {
    this.head = this.tail = 0;
  }

  private grow(): void {
    // Full: head === tail after the last push. Unroll into a buffer twice the size.
    const old = this.buf;
    const n = old.length;
    const next = new Int32Array(n * 2);
    next.set(old.subarray(this.head));
    next.set(old.subarray(0, this.head), n - this.head);
    this.buf = next;
    this.mask = n * 2 - 1;
    this.head = 0;
    this.tail = n;
  }
}

const FILTER = BLOCK_LIGHT_FILTER;
const EMISSION = BLOCK_LIGHT_EMISSION;

// ---------------------------------------------------------------------------------------------
// Chunk-local initial lighting
// ---------------------------------------------------------------------------------------------

const localQueue = new IntQueue(1 << 15);
const heights = new Int16Array(256);

/**
 * Spreads one light kind inside a single chunk from the indices in `q` (layer << 8 | z << 4 | x;
 * layer = y - MIN_Y, so everything in this chunk-local pass works on layers 0..CHUNK_HEIGHT-1).
 * `shift` is 4 for sky light, 0 for block light.
 */
function spreadLocal(blocks: Uint16Array, light: Uint8Array, q: IntQueue, sky: boolean): void {
  const shift = sky ? 4 : 0;
  const keep = sky ? 0x0f : 0xf0;
  while (!q.isEmpty) {
    const i = q.shift();
    const v = (light[i]! >> shift) & 15;
    if (v <= 1) continue;
    const x = i & 15;
    const z = (i >> 4) & 15;
    const y = i >> 8;
    for (let d = 0; d < 6; d++) {
      let j: number;
      switch (d) {
        case 0: if (x === 15) continue; j = i + 1; break;
        case 1: if (x === 0) continue; j = i - 1; break;
        case 2: if (y === CHUNK_HEIGHT - 1) continue; j = i + 256; break;
        case 3: if (y === 0) continue; j = i - 256; break;
        case 4: if (z === 15) continue; j = i + 16; break;
        default: if (z === 0) continue; j = i - 16; break;
      }
      const f = FILTER[blocks[j]!]!;
      if (f >= MAX_LIGHT) continue;
      const nv = sky && d === 3 && v === MAX_LIGHT && f === 0 ? MAX_LIGHT : v - 1 - f;
      if (nv > ((light[j]! >> shift) & 15)) {
        light[j] = (light[j]! & keep) | (nv << shift);
        q.push(j);
      }
    }
  }
}

/**
 * Computes sky and block light for one chunk in isolation (no light enters or leaves through its
 * sides). Overwrites `light`. Pure apart from module scratch buffers, so it is worker-safe.
 */
export function computeChunkLightArrays(blocks: Uint16Array, light: Uint8Array): void {
  if (blocks.length !== CHUNK_VOLUME || light.length !== CHUNK_VOLUME) throw new Error('computeChunkLight: bad array size');
  light.fill(0);
  const q = localQueue;
  q.clear();

  // Sky: column pass. A cell is 15 when every cell from it up to the top of the world is clear.
  for (let col = 0; col < 256; col++) {
    let y = CHUNK_HEIGHT - 1;
    let i = (y << 8) | col;
    while (y >= 0 && FILTER[blocks[i]!] === 0) {
      light[i] = MAX_LIGHT << 4;
      y--;
      i -= 256;
    }
    heights[col] = y + 1;
  }
  // Seeds: open-sky cells next to a darker column, plus each column's lowest open cell (light
  // continues down into leaves/water there).
  for (let col = 0; col < 256; col++) {
    const h = heights[col]!;
    if (h >= CHUNK_HEIGHT) continue;
    const x = col & 15;
    const z = col >> 4;
    let top = h + 1;
    if (x > 0) top = Math.max(top, heights[col - 1]!);
    if (x < 15) top = Math.max(top, heights[col + 1]!);
    if (z > 0) top = Math.max(top, heights[col - 16]!);
    if (z < 15) top = Math.max(top, heights[col + 16]!);
    top = Math.min(top, CHUNK_HEIGHT);
    for (let y = h; y < top; y++) q.push((y << 8) | col);
  }
  spreadLocal(blocks, light, q, true);

  // Block light: seed every emitter.
  for (let i = 0; i < CHUNK_VOLUME; i++) {
    const e = EMISSION[blocks[i]!]!;
    if (e > 0) {
      light[i] = (light[i]! & 0xf0) | e;
      q.push(i);
    }
  }
  spreadLocal(blocks, light, q, false);
}

/** `computeChunkLightArrays` for a chunk's own arrays. */
export function computeChunkLight(chunk: Chunk): void {
  computeChunkLightArrays(chunk.blocks, chunk.light);
}

// ---------------------------------------------------------------------------------------------
// World-level engine: cross-chunk stitching and incremental updates
// ---------------------------------------------------------------------------------------------

/** Neighbour directions; index 3 is straight down (the sky-light shaft rule). */
const DX = [1, -1, 0, 0, 0, 0];
const DY = [0, 0, 1, -1, 0, 0];
const DZ = [0, 0, 0, 0, 1, -1];
const DOWN = 3;

export interface LightStats {
  /** Chunks stitched to their neighbours. */
  stitches: number;
  /** Milliseconds spent in the last stitch / moving average. */
  lastStitchMs: number;
  avgStitchMs: number;
  /** Block edits relit and the time spent on the last one. */
  edits: number;
  lastEditMs: number;
  /** Cells whose light changed in the last operation. */
  lastChangedCells: number;
}

/**
 * Keeps the light of a `World` correct across chunk borders and block edits. Every section whose
 * light changes (plus the neighbouring sections whose padded copies include the changed cell) is
 * marked dirty so it re-meshes.
 */
export class LightEngine {
  /** Increase queue: world x, y, z triples. */
  private readonly addQ = new IntQueue(1 << 12);
  /** Removal queue: world x, y, z, old level quads. */
  private readonly remQ = new IntQueue(1 << 12);
  private readonly touched = new Set<number>();
  private lastTouchedKey = -1;
  private changed = 0;
  private cacheCx = Number.NaN;
  private cacheCz = Number.NaN;
  private cacheChunk: Chunk | undefined;
  readonly stats: LightStats = { stitches: 0, lastStitchMs: 0, avgStitchMs: 0, edits: 0, lastEditMs: 0, lastChangedCells: 0 };

  constructor(readonly world: World) {}

  /** Chunks may have been added or removed since the last operation. */
  private invalidateCache(): void {
    this.cacheCx = this.cacheCz = Number.NaN;
    this.cacheChunk = undefined;
  }

  private chunkAt(wx: number, wz: number): Chunk | undefined {
    const cx = wx >> 4;
    const cz = wz >> 4;
    if (cx !== this.cacheCx || cz !== this.cacheCz) {
      this.cacheCx = cx;
      this.cacheCz = cz;
      this.cacheChunk = this.world.getChunk(cx, cz);
    }
    return this.cacheChunk;
  }

  /** Records that the light of world cell (x, y, z) changed: its section and every section whose padded copy contains it. */
  private touch(x: number, y: number, z: number): void {
    this.changed++;
    const lx = x & 15;
    const ly = y & 15;
    const lz = z & 15;
    const cx = x >> 4;
    const cz = z >> 4;
    const sy = sectionOf(y);
    if (lx !== 0 && lx !== 15 && ly !== 0 && ly !== 15 && lz !== 0 && lz !== 15) {
      const key = sectionKey(cx, sy, cz);
      if (key !== this.lastTouchedKey) {
        this.lastTouchedKey = key;
        this.touched.add(key);
      }
      return;
    }
    const x0 = lx === 0 ? -1 : 0;
    const x1 = lx === 15 ? 1 : 0;
    const z0 = lz === 0 ? -1 : 0;
    const z1 = lz === 15 ? 1 : 0;
    const y0 = ly === 0 && sy > 0 ? -1 : 0;
    const y1 = ly === 15 && sy < SECTION_COUNT - 1 ? 1 : 0;
    for (let dz = z0; dz <= z1; dz++) {
      for (let dx = x0; dx <= x1; dx++) {
        for (let dy = y0; dy <= y1; dy++) this.touched.add(sectionKey(cx + dx, sy + dy, cz + dz));
      }
    }
  }

  private flushDirty(): void {
    for (const key of this.touched) {
      const { cx, sy, cz } = decodeSectionKey(key);
      this.world.getChunk(cx, cz)?.markSectionDirty(sy);
    }
    this.touched.clear();
    this.lastTouchedKey = -1;
    this.stats.lastChangedCells = this.changed;
    this.changed = 0;
  }

  private pushAdd(x: number, y: number, z: number): void {
    this.addQ.push(x);
    this.addQ.push(y);
    this.addQ.push(z);
  }

  private pushRemove(x: number, y: number, z: number, level: number): void {
    this.remQ.push(x);
    this.remQ.push(y);
    this.remQ.push(z);
    this.remQ.push(level);
  }

  /** Runs the increase BFS for one light kind until the add queue is empty. */
  private runAdd(sky: boolean): void {
    const shift = sky ? 4 : 0;
    const keep = sky ? 0x0f : 0xf0;
    const q = this.addQ;
    while (!q.isEmpty) {
      const x = q.shift();
      const y = q.shift();
      const z = q.shift();
      const c = this.chunkAt(x, z);
      if (!c) continue;
      const v = (c.light[((y - MIN_Y) << 8) | ((z & 15) << 4) | (x & 15)]! >> shift) & 15;
      if (v <= 1) continue;
      for (let d = 0; d < 6; d++) {
        const ny = y + DY[d]!;
        if (ny < MIN_Y || ny > MAX_Y) continue;
        const nx = x + DX[d]!;
        const nz = z + DZ[d]!;
        const nc = this.chunkAt(nx, nz);
        if (!nc) continue;
        const j = ((ny - MIN_Y) << 8) | ((nz & 15) << 4) | (nx & 15);
        const f = FILTER[nc.blocks[j]!]!;
        if (f >= MAX_LIGHT) continue;
        const nv = sky && d === DOWN && v === MAX_LIGHT && f === 0 ? MAX_LIGHT : v - 1 - f;
        if (nv > ((nc.light[j]! >> shift) & 15)) {
          nc.light[j] = (nc.light[j]! & keep) | (nv << shift);
          this.touch(nx, ny, nz);
          this.pushAdd(nx, ny, nz);
        }
      }
    }
  }

  /**
   * Runs the removal BFS for one light kind. Cells that were lit by a removed cell are darkened;
   * brighter cells met on the way (and emitters) are queued on the add queue to refill the area.
   */
  private runRemove(sky: boolean): void {
    const shift = sky ? 4 : 0;
    const keep = sky ? 0x0f : 0xf0;
    const q = this.remQ;
    while (!q.isEmpty) {
      const x = q.shift();
      const y = q.shift();
      const z = q.shift();
      const v = q.shift();
      for (let d = 0; d < 6; d++) {
        const ny = y + DY[d]!;
        if (ny < MIN_Y || ny > MAX_Y) continue;
        const nx = x + DX[d]!;
        const nz = z + DZ[d]!;
        const nc = this.chunkAt(nx, nz);
        if (!nc) continue;
        const j = ((ny - MIN_Y) << 8) | ((nz & 15) << 4) | (nx & 15);
        const n = (nc.light[j]! >> shift) & 15;
        if (n === 0) continue;
        if (n < v || (sky && d === DOWN && v === MAX_LIGHT && n === MAX_LIGHT)) {
          nc.light[j] = nc.light[j]! & keep;
          this.touch(nx, ny, nz);
          this.pushRemove(nx, ny, nz, n);
          if (!sky) {
            const e = EMISSION[nc.blocks[j]!]!;
            if (e > 0) {
              nc.light[j] = (nc.light[j]! & keep) | e;
              this.pushAdd(nx, ny, nz);
            }
          }
        } else {
          this.pushAdd(nx, ny, nz);
        }
      }
    }
  }

  /** Queues the loaded, in-range neighbours of a cell as light sources (they flow back into it). */
  private pushNeighbours(x: number, y: number, z: number): void {
    for (let d = 0; d < 6; d++) {
      const ny = y + DY[d]!;
      if (ny < MIN_Y || ny > MAX_Y) continue;
      this.pushAdd(x + DX[d]!, ny, z + DZ[d]!);
    }
  }

  /**
   * Updates light after block (x, y, z) changed from `oldId` to `newId` (the World already holds
   * `newId`). Marks every section whose light changed dirty.
   */
  onBlockChanged(x: number, y: number, z: number, oldId: number, newId: number): void {
    if (y < MIN_Y || y > MAX_Y) return;
    this.invalidateCache();
    const c = this.chunkAt(x, z);
    if (!c) return;
    const t0 = now();
    const i = ((y - MIN_Y) << 8) | ((z & 15) << 4) | (x & 15);
    const filterChanged = FILTER[oldId] !== FILTER[newId];
    const clear = FILTER[newId]! < MAX_LIGHT;

    // Block light.
    if (filterChanged || EMISSION[oldId] !== EMISSION[newId]) {
      const old = c.light[i]! & 15;
      if (old > 0) {
        c.light[i] = c.light[i]! & 0xf0;
        this.touch(x, y, z);
        this.pushRemove(x, y, z, old);
      }
      this.runRemove(false);
      const e = EMISSION[newId]!;
      if (e > 0) {
        c.light[i] = (c.light[i]! & 0xf0) | e;
        this.touch(x, y, z);
        this.pushAdd(x, y, z);
      }
      if (clear) this.pushNeighbours(x, y, z);
      this.runAdd(false);
    }

    // Sky light only depends on how much light the cell lets through.
    if (filterChanged) {
      const old = c.light[i]! >> 4;
      if (old > 0) {
        c.light[i] = c.light[i]! & 0x0f;
        this.touch(x, y, z);
        this.pushRemove(x, y, z, old);
      }
      this.runRemove(true);
      if (clear) {
        if (y === MAX_Y) {
          // Directly under the open sky.
          c.light[i] = (c.light[i]! & 0x0f) | ((MAX_LIGHT - FILTER[newId]!) << 4);
          this.touch(x, y, z);
          this.pushAdd(x, y, z);
        }
        this.pushNeighbours(x, y, z);
      }
      this.runAdd(true);
    }

    this.flushDirty();
    this.stats.edits++;
    this.stats.lastEditMs = now() - t0;
  }

  /**
   * Lets light flow between chunk (cx, cz) and its loaded horizontal neighbours, in both
   * directions, and onward through any loaded chunks. Call right after adding a chunk whose own
   * light was computed with `computeChunkLight`, before it is meshed.
   */
  stitchChunk(cx: number, cz: number): void {
    const chunk = this.world.getChunk(cx, cz);
    if (!chunk) return;
    this.invalidateCache();
    const t0 = now();
    const bx = cx * 16;
    const bz = cz * 16;
    for (const sky of [true, false]) {
      const shift = sky ? 4 : 0;
      for (let side = 0; side < 4; side++) {
        // side 0: +X, 1: -X, 2: +Z, 3: -Z
        const ncx = cx + (side === 0 ? 1 : side === 1 ? -1 : 0);
        const ncz = cz + (side === 2 ? 1 : side === 3 ? -1 : 0);
        const nb = this.world.getChunk(ncx, ncz);
        if (!nb) continue;
        for (let t = 0; t < 16; t++) {
          // Local coords of the border cell in `chunk` (a) and in `nb` (b).
          let ax: number, az: number, bxl: number, bzl: number;
          if (side < 2) {
            ax = side === 0 ? 15 : 0;
            bxl = 15 - ax;
            az = bzl = t;
          } else {
            az = side === 2 ? 15 : 0;
            bzl = 15 - az;
            ax = bxl = t;
          }
          for (let layer = 0; layer < CHUNK_HEIGHT; layer++) {
            const y = layer + MIN_Y;
            const ia = (layer << 8) | (az << 4) | ax;
            const ib = (layer << 8) | (bzl << 4) | bxl;
            const la = (chunk.light[ia]! >> shift) & 15;
            const lb = (nb.light[ib]! >> shift) & 15;
            if (la - 1 - FILTER[nb.blocks[ib]!]! > lb) this.pushAdd(bx + ax, y, bz + az);
            else if (lb - 1 - FILTER[chunk.blocks[ia]!]! > la) this.pushAdd(ncx * 16 + bxl, y, ncz * 16 + bzl);
          }
        }
      }
      this.runAdd(sky);
    }
    this.flushDirty();
    const ms = now() - t0;
    this.stats.lastStitchMs = ms;
    this.stats.avgStitchMs = this.stats.stitches === 0 ? ms : this.stats.avgStitchMs * 0.95 + ms * 0.05;
    this.stats.stitches++;
  }
}

function now(): number {
  return typeof performance !== 'undefined' ? performance.now() : Date.now();
}
