import { CHUNKS_STORE, MAP_PACKAGES_STORE, WORLDS_STORE, openDatabase, req, txDone } from './db';
import type { StoredMapPackage } from '@voxel/mapgen';
import type { ByteCodec } from './compression';
import {
  normalizeGameMode,
  normalizeGeneratorKind,
  type GameMode,
  type GeneratorKind,
  type GeoBBox,
  type SavedInventory,
  type SavedItemEntity,
  type SavedMob,
} from '@voxel/shared';

/**
 * Version of the `WorldMeta` layout.
 * 2 (Milestone 7): game mode 'normal' became 'survival'; player vitals + inventory; item entities.
 * 3 (Milestone 8): living mobs (`mobs`, by type name). Older records simply have none.
 * 4 (map worlds, phase A): `generator` ('terrain' | 'map'); older worlds are terrain worlds.
 */
export const WORLD_FORMAT_VERSION = 4;

export type { GameMode, GeneratorKind };

export interface SavedPlayer {
  x: number;
  y: number;
  z: number;
  yaw: number;
  pitch: number;
  flying: boolean;
  /** Respawn point; absent until the player first spawned. */
  spawn?: { x: number; y: number; z: number };
  /** Selected hotbar slot, 0-8. */
  hotbar?: number;
  /** Survival vitals (Milestone 7). Absent in older saves: full health and hunger. */
  health?: number;
  hunger?: number;
  saturation?: number;
  /** Seconds of breath left. */
  air?: number;
  /** Inventory slots by item name (Milestone 7). */
  inventory?: SavedInventory;
}

/** One record of the `worlds` store. */
export interface WorldMeta {
  id: string;
  name: string;
  seed: number;
  /** How chunks are generated (format 4; `migrateWorldMeta` makes older worlds `terrain`). */
  generator: GeneratorKind;
  /** Map worlds: key of the MapPackage in the map package store (phase E; absent for the stub). */
  mapPackageId?: string;
  /** Map worlds: geographic bounds, [south, west, north, east] degrees. */
  bbox?: GeoBBox;
  createdAt: number;
  lastPlayed: number;
  formatVersion: number;
  gameMode: GameMode;
  /** Block names in ID order at the last save (informational; chunks carry their own palette). */
  palette: string[];
  /** `WorldTime.ticks`. */
  timeTicks: number;
  /** Absent for a world that was never entered. */
  player?: SavedPlayer;
  /** Dropped items lying in the world (Milestone 7). */
  itemEntities?: SavedItemEntity[];
  /** Living mobs (Milestone 8), saved by type name wherever they are (loaded or not). */
  mobs?: SavedMob[];
}

/** Upgrades a meta record read from an older version (in memory; written back on next save). */
export function migrateWorldMeta(meta: WorldMeta): WorldMeta {
  return {
    ...meta,
    gameMode: normalizeGameMode(meta.gameMode),
    generator: normalizeGeneratorKind((meta as Partial<WorldMeta>).generator),
  };
}

/** One record of the `mapPackages` store. */
export interface MapPackageRecord extends StoredMapPackage {
  id: string;
  savedAt: number;
}

/** One record of the `chunks` store; key [worldId, cx, cz]. Only modified chunks are stored. */
export interface ChunkRecord {
  worldId: string;
  cx: number;
  cz: number;
  /** `CHUNK_FORMAT_VERSION` of the encoded data. */
  format: number;
  /** How `data` is compressed on top of the RLE. */
  codec: ByteCodec;
  /** Chunk-local palette of block names (see shared chunkCodec). */
  palette: string[];
  data: ArrayBuffer;
  savedAt: number;
}

function worldRange(worldId: string): IDBKeyRange {
  return IDBKeyRange.bound([worldId, -Infinity, -Infinity], [worldId, Infinity, Infinity]);
}

/**
 * The IndexedDB save store: world metadata and modified chunks. Every method catches nothing on
 * purpose; callers (SaveManager, menus) wrap calls and degrade to "saving disabled".
 */
export class WorldStore {
  private constructor(private readonly db: IDBDatabase) {}

  /** Opens the store, or returns undefined (with a console warning) if IndexedDB is unusable. */
  static async open(factory?: IDBFactory, name?: string): Promise<WorldStore | undefined> {
    try {
      const db = await openDatabase(factory, name);
      return new WorldStore(db);
    } catch (err) {
      console.warn('Saving disabled:', err);
      return undefined;
    }
  }

  close(): void {
    this.db.close();
  }

  /** All worlds, most recently played first. */
  async listWorlds(): Promise<WorldMeta[]> {
    const tx = this.db.transaction(WORLDS_STORE, 'readonly');
    const all = (await req(tx.objectStore(WORLDS_STORE).getAll())) as WorldMeta[];
    return all.map(migrateWorldMeta).sort((a, b) => b.lastPlayed - a.lastPlayed);
  }

  async getWorld(id: string): Promise<WorldMeta | undefined> {
    const tx = this.db.transaction(WORLDS_STORE, 'readonly');
    const meta = (await req(tx.objectStore(WORLDS_STORE).get(id))) as WorldMeta | undefined;
    return meta && migrateWorldMeta(meta);
  }

  async putWorld(meta: WorldMeta): Promise<void> {
    const tx = this.db.transaction(WORLDS_STORE, 'readwrite');
    tx.objectStore(WORLDS_STORE).put(meta);
    await txDone(tx);
  }

  async renameWorld(id: string, name: string): Promise<void> {
    const tx = this.db.transaction(WORLDS_STORE, 'readwrite');
    const store = tx.objectStore(WORLDS_STORE);
    const meta = (await req(store.get(id))) as WorldMeta | undefined;
    if (meta) store.put({ ...meta, name });
    await txDone(tx);
  }

  /** Deletes a world's meta, all of its chunks and its map package in one transaction. */
  async deleteWorld(id: string): Promise<void> {
    const tx = this.db.transaction([WORLDS_STORE, CHUNKS_STORE, MAP_PACKAGES_STORE], 'readwrite');
    const worlds = tx.objectStore(WORLDS_STORE);
    const meta = (await req(worlds.get(id))) as WorldMeta | undefined;
    if (meta?.mapPackageId) tx.objectStore(MAP_PACKAGES_STORE).delete(meta.mapPackageId);
    worlds.delete(id);
    tx.objectStore(CHUNKS_STORE).delete(worldRange(id));
    await txDone(tx);
  }

  async putMapPackage(id: string, stored: StoredMapPackage): Promise<void> {
    const tx = this.db.transaction(MAP_PACKAGES_STORE, 'readwrite');
    const rec: MapPackageRecord = { id, pkg: stored.pkg, osm: stored.osm, bbox: stored.bbox, scale: stored.scale, savedAt: Date.now() };
    // Elevation tiles (terrain) are kept so the package can be rebuilt offline.
    if (stored.dem?.length) rec.dem = stored.dem.map((t) => ({ z: t.z, x: t.x, y: t.y, png: t.png }));
    tx.objectStore(MAP_PACKAGES_STORE).put(rec);
    await txDone(tx);
  }

  async getMapPackage(id: string): Promise<MapPackageRecord | undefined> {
    const tx = this.db.transaction(MAP_PACKAGES_STORE, 'readonly');
    return (await req(tx.objectStore(MAP_PACKAGES_STORE).get(id))) as MapPackageRecord | undefined;
  }

  /** [cx, cz] of every stored chunk of a world, via a key cursor (values are not read). */
  async listChunkCoords(worldId: string): Promise<[number, number][]> {
    const tx = this.db.transaction(CHUNKS_STORE, 'readonly');
    const keys = (await req(tx.objectStore(CHUNKS_STORE).getAllKeys(worldRange(worldId)))) as unknown as [string, number, number][];
    return keys.map((k) => [k[1], k[2]]);
  }

  async countChunks(worldId: string): Promise<number> {
    const tx = this.db.transaction(CHUNKS_STORE, 'readonly');
    return req(tx.objectStore(CHUNKS_STORE).count(worldRange(worldId)));
  }

  async getChunk(worldId: string, cx: number, cz: number): Promise<ChunkRecord | undefined> {
    const tx = this.db.transaction(CHUNKS_STORE, 'readonly');
    return (await req(tx.objectStore(CHUNKS_STORE).get([worldId, cx, cz]))) as ChunkRecord | undefined;
  }

  /**
   * Writes chunks and (optionally) the world meta in ONE transaction. The transaction is created
   * synchronously, so calling this from a `pagehide` handler queues the write immediately.
   */
  saveBatch(meta: WorldMeta | undefined, chunks: readonly ChunkRecord[]): Promise<void> {
    const stores = meta ? [WORLDS_STORE, CHUNKS_STORE] : [CHUNKS_STORE];
    const tx = this.db.transaction(stores, 'readwrite');
    const done = txDone(tx);
    if (meta) tx.objectStore(WORLDS_STORE).put(meta);
    const cs = tx.objectStore(CHUNKS_STORE);
    for (const c of chunks) cs.put(c);
    // Commit now instead of when the event loop goes idle: gives a write queued from pagehide the
    // best chance to land before the page is torn down.
    try {
      tx.commit?.();
    } catch {
      // older browsers / already committing
    }
    return done;
  }
}
