/**
 * Item registry (Milestone 7). Every item has a stable string `name` that saves use; numeric IDs
 * are runtime-only indices into `ITEMS` and may change between versions.
 *
 * - Block items place their block (`block`), one per placeable block, named after the block.
 * - Tools have a family (`tool.kind`), a tier and a durability; they never stack.
 * - Food restores hunger when eaten (hold right click).
 */
import { BLOCKS, BlockId, ToolTier, baseBlock, type ToolKind } from '../world/blocks';

export interface ToolInfo {
  kind: ToolKind;
  tier: ToolTier;
  /** Uses before the tool breaks. */
  durability: number;
  /** Damage dealt when hitting a mob (used from Milestone 8). */
  attackDamage: number;
}

export interface FoodInfo {
  /** Hunger points restored (of 20). */
  hunger: number;
  /** Saturation added (hidden hunger buffer). */
  saturation: number;
  /** Seconds of holding right click to eat one. */
  eatSeconds: number;
}

export interface ItemDef {
  /** Runtime index into ITEMS. Never saved. */
  id: number;
  /** Stable save name, lowercase with underscores. */
  name: string;
  /** Human readable name for tooltips. */
  label: string;
  maxStack: number;
  /** Block placed by this item. */
  block?: number;
  tool?: ToolInfo;
  food?: FoodInfo;
}

/** One inventory stack. `damage` is how much durability a tool has used (0 for everything else). */
export interface ItemStack {
  item: number;
  count: number;
  damage: number;
}

/** A slot is either empty (null) or holds a stack with count >= 1. */
export type Slot = ItemStack | null;

export const MAX_STACK = 64;

/** Speed multiplier of each tier when the right tool is used. Index = ToolTier. */
export const TIER_SPEED: readonly number[] = [1, 2, 4, 6];
/** Durability per tier. Index = ToolTier. */
export const TIER_DURABILITY: readonly number[] = [0, 64, 140, 256];

/** Blocks that do not get an item: air, water and bedrock cannot be held. */
const NO_ITEM_BLOCKS = new Set<number>([BlockId.Air, BlockId.Water, BlockId.Bedrock]);

function labelOf(name: string): string {
  const s = name.replace(/_/g, ' ');
  return s.charAt(0).toUpperCase() + s.slice(1);
}

type ItemSpec = Omit<ItemDef, 'id' | 'label'> & { label?: string };

const SPECS: ItemSpec[] = [];
for (const b of BLOCKS) {
  // Variants (top slab, turned stairs...) are placed with their family's base item.
  if (NO_ITEM_BLOCKS.has(b.id) || b.variantOf !== undefined) continue;
  SPECS.push({ name: b.name, maxStack: MAX_STACK, block: b.id });
}

SPECS.push(
  { name: 'stick', maxStack: MAX_STACK },
  { name: 'coal', maxStack: MAX_STACK },
  { name: 'iron_ingot', maxStack: MAX_STACK },
  { name: 'apple', maxStack: MAX_STACK, food: { hunger: 4, saturation: 2.4, eatSeconds: 1.6 } },
  // Mob drops (Milestone 8). Raw meat is "cooked" by crafting it with coal (there is no furnace).
  { name: 'raw_meat', maxStack: MAX_STACK, food: { hunger: 2, saturation: 1.2, eatSeconds: 1.6 } },
  { name: 'cooked_meat', maxStack: MAX_STACK, food: { hunger: 8, saturation: 6, eatSeconds: 1.6 } },
  { name: 'feather', maxStack: MAX_STACK },
);

const MATERIALS: readonly [string, string, ToolTier][] = [
  ['wooden', 'Wooden', ToolTier.Wood],
  ['stone', 'Stone', ToolTier.Stone],
  ['iron', 'Iron', ToolTier.Iron],
];
const KINDS: readonly [ToolKind, number][] = [
  ['pickaxe', 2],
  ['axe', 3],
  ['shovel', 1],
  ['sword', 4],
];
for (const [mat, matLabel, tier] of MATERIALS) {
  for (const [kind, baseDamage] of KINDS) {
    SPECS.push({
      name: `${mat}_${kind}`,
      label: `${matLabel} ${kind}`,
      maxStack: 1,
      tool: { kind, tier, durability: TIER_DURABILITY[tier]!, attackDamage: baseDamage + tier },
    });
  }
}

/** All items indexed by runtime ID. */
export const ITEMS: readonly ItemDef[] = SPECS.map((s, id) => ({ ...s, id, label: s.label ?? labelOf(s.name) }));
export const ITEM_COUNT = ITEMS.length;

const BY_NAME = new Map(ITEMS.map((d) => [d.name, d]));
if (BY_NAME.size !== ITEMS.length) throw new Error('Duplicate item names in the item registry');
const BY_BLOCK = new Map<number, ItemDef>();
for (const d of ITEMS) if (d.block !== undefined) BY_BLOCK.set(d.block, d);

export function getItemDef(id: number): ItemDef {
  const d = ITEMS[id];
  if (!d) throw new Error(`Unknown item id ${id}`);
  return d;
}

export function itemByName(name: string): ItemDef | undefined {
  return BY_NAME.get(name);
}

/** Item ID by name; throws for unknown names (use for code-defined names only). */
export function itemId(name: string): number {
  const d = BY_NAME.get(name);
  if (!d) throw new Error(`Unknown item '${name}'`);
  return d.id;
}

/** The item that places `blockId` (for a variant, its family's base item), if any. */
export function itemForBlock(blockId: number): ItemDef | undefined {
  return BY_BLOCK.get(baseBlock(blockId));
}

export function createStack(item: number | string, count = 1, damage = 0): ItemStack {
  return { item: typeof item === 'string' ? itemId(item) : item, count, damage };
}

export function maxStackOf(stack: ItemStack): number {
  return getItemDef(stack.item).maxStack;
}

/** Same item and same wear, so the stacks may merge (if their max stack allows). */
export function stacksMatch(a: ItemStack, b: ItemStack): boolean {
  return a.item === b.item && a.damage === b.damage;
}

export function cloneStack(s: ItemStack): ItemStack {
  return { item: s.item, count: s.count, damage: s.damage };
}

/** Remaining uses of a tool stack, or undefined for non-tools. */
export function remainingDurability(stack: ItemStack): number | undefined {
  const t = getItemDef(stack.item).tool;
  return t ? Math.max(0, t.durability - stack.damage) : undefined;
}

// --- Saving (by name) ---------------------------------------------------------------------------

export interface SavedStack {
  name: string;
  count: number;
  /** Omitted when 0. */
  damage?: number;
}

export function stackToSaved(s: ItemStack): SavedStack {
  const out: SavedStack = { name: getItemDef(s.item).name, count: s.count };
  if (s.damage) out.damage = s.damage;
  return out;
}

/** Maps a saved stack back to current IDs. Unknown names and broken data give null. */
export function stackFromSaved(s: SavedStack | null | undefined): Slot {
  if (!s || typeof s.name !== 'string') return null;
  const def = itemByName(s.name);
  if (!def) return null;
  const count = Math.min(def.maxStack, Math.floor(Number(s.count)));
  if (!(count >= 1)) return null;
  const damage = def.tool ? Math.max(0, Math.min(def.tool.durability - 1, Math.floor(Number(s.damage ?? 0)) || 0)) : 0;
  return { item: def.id, count, damage };
}
