// --- Map worlds, phase D: shaped blocks ---------------------------------------------------------
// Appended in ID order after the concrete set. Each family's base block comes first and carries
// the item; the other orientations follow it.

/** Adds a family: `[base, ...variants]` share everything but name and model. */
function addFamily(base: BlockDef, names: readonly string[], models: readonly BlockModel[], placement?: PlacementRule): void {
  const baseId = DEFS.length;
  names.forEach((name, i) => {
    const def: BlockDef = { ...base, id: baseId + i, name, shape: BlockShape.Model, model: models[i]! };
    if (i === 0) {
      if (placement) def.placement = placement;
    } else def.variantOf = baseId;
    DEFS.push(def);
  });
}

/** Shaped blocks are see-through for culling (neighbour faces stay) but drawn in the opaque pass. */
function shaped(material: BlockDef): BlockDef {
  return { ...material, id: 0, name: '', transparent: true, opaque: false, renderPass: RenderPass.Opaque };
}

const SLAB_BOTTOM: BlockModel = { kind: 'boxes', boxes: [[0, 0, 0, 16, 8, 16]] };
const SLAB_TOP: BlockModel = { kind: 'boxes', boxes: [[0, 8, 0, 16, 16, 16]] };
/** Stairs: a bottom slab plus the upper half on the high (facing) side: north, east, south, west. */
const STAIRS: readonly BlockModel[] = (
  [
    [0, 8, 0, 16, 16, 8],
    [8, 8, 0, 16, 16, 16],
    [0, 8, 8, 16, 16, 16],
    [0, 8, 0, 8, 16, 16],
  ] as const
).map((upper): BlockModel => ({ kind: 'boxes', boxes: [[0, 0, 0, 16, 8, 16], upper] }));

/** Sound of a material block (older blocks have none in their definition). */
function soundOf(material: BlockDef): BlockSound {
  return material.sound ?? (material.name === 'planks' ? 'wood' : 'stone');
}

/** Slab materials (bottom and top slab each). Slabs and stairs block light like the full block. */
const SLAB_MATERIALS = ['stone', 'planks', 'stone_bricks', 'brick', 'paving', 'asphalt', 'concrete_gray', 'roof_tiles', 'roof_slate'] as const;
const STAIR_MATERIALS = ['planks', 'stone_bricks', 'brick', 'roof_tiles', 'roof_slate'] as const;

for (const m of SLAB_MATERIALS) {
  const mat = DEFS.find((d) => d.name === m)!;
  addFamily({ ...shaped(mat), lightFilter: MAX_LIGHT, sound: soundOf(mat) }, [`${m}_slab`, `${m}_slab_top`], [SLAB_BOTTOM, SLAB_TOP], 'slab');
}
for (const m of STAIR_MATERIALS) {
  const mat = DEFS.find((d) => d.name === m)!;
  addFamily({ ...shaped(mat), lightFilter: MAX_LIGHT, sound: soundOf(mat) }, [`${m}_stairs`, `${m}_stairs_e`, `${m}_stairs_s`, `${m}_stairs_w`], STAIRS, 'facing');
}

// Connecting posts: fences (two rails), walls (thick, nearly full height) and glass panes.
{
  const planks = DEFS.find((d) => d.name === 'planks')!;
  const bricks = DEFS.find((d) => d.name === 'stone_bricks')!;
  const glass = DEFS.find((d) => d.name === 'glass')!;
  addFamily({ ...shaped(planks), sound: 'wood' }, ['wooden_fence'], [
    { kind: 'connect', group: 'fence', post: [6, 0, 6, 10, 16, 10], arms: [{ half: 1, y0: 6, y1: 9 }, { half: 1, y0: 12, y1: 15 }] },
  ]);
  addFamily({ ...shaped(bricks), sound: 'stone' }, ['stone_wall'], [{ kind: 'connect', group: 'wall', post: [4, 0, 4, 12, 16, 12], arms: [{ half: 3, y0: 0, y1: 13 }] }]);
  addFamily({ ...glass, id: 0, name: '', sound: 'glass' }, ['glass_pane'], [{ kind: 'connect', group: 'pane', post: [7, 0, 7, 9, 16, 9], arms: [{ half: 1, y0: 0, y1: 16 }] }]);
}

// Rails: flat decals (not solid), straight and curved, one ID per orientation.
{
  const rail: BlockDef = {
    id: 0,
    name: '',
    solid: false,
    transparent: true,
    opaque: false,
    renderPass: RenderPass.Opaque, // alpha cutout
    textures: all(T.rail),
    hardness: 0.7,
    tool: 'pickaxe',
    sound: 'stone',
  };
  addFamily(rail, ['rail', 'rail_ew'], [{ kind: 'flat', rotation: 0 }, { kind: 'flat', rotation: 1 }], 'axis');
  const curves: BlockModel[] = [
    { kind: 'flat', rotation: 0 },
    { kind: 'flat', rotation: 1 },
    { kind: 'flat', rotation: 2 },
    { kind: 'flat', rotation: 3 },
  ];
  addFamily({ ...rail, textures: all(T.rail_curve) }, ['rail_curve', 'rail_curve_e', 'rail_curve_s', 'rail_curve_w'], curves, 'facing');
}

/** All block definitions indexed by ID. */
export const BLOCKS: readonly BlockDef[] = DEFS;
DEFS.forEach((d, i) => {
  if (d.id !== i) throw new Error(`Block registry out of order: ${d.name} has id ${d.id} at index ${i}`);
});

export const BLOCK_COUNT = DEFS.length;

/** Flat lookup tables for hot loops (mesher). Index by block ID. */
export const BLOCK_OPAQUE = Uint8Array.from(DEFS, (d) => (d.opaque ? 1 : 0));
export const BLOCK_RENDER_PASS = Uint8Array.from(DEFS, (d) => d.renderPass);
export const BLOCK_SHAPE = Uint8Array.from(DEFS, (d) => d.shape ?? BlockShape.Cube);
/** Light emitted by each block, 0..15. */
export const BLOCK_LIGHT_EMISSION = Uint8Array.from(DEFS, (d) => d.lightEmission ?? 0);
/**
 * Extra attenuation when light enters a cell of this block: 0 for clear blocks, small for leaves
 * and water, and `MAX_LIGHT` (blocks everything) for opaque blocks.
 */
export const BLOCK_LIGHT_FILTER = Uint8Array.from(DEFS, (d) => (d.opaque ? MAX_LIGHT : Math.min(MAX_LIGHT, d.lightFilter ?? 0)));
/** Per block, three layers: [top, side, bottom]. */
export const BLOCK_FACE_LAYERS = Uint16Array.from(DEFS.flatMap((d) => [d.textures.top, d.textures.side, d.textures.bottom]));

export function getBlockDef(id: number): BlockDef {
  const def = DEFS[id];
  if (!def) throw new Error(`Unknown block id ${id}`);
  return def;
}

/** Mining hardness of a block (default 1; negative = unbreakable). */
export function blockHardness(id: number): number {
  return DEFS[id]?.hardness ?? 1;
}

export function blockByName(name: string): BlockDef | undefined {
  return DEFS.find((d) => d.name === name);
}

/** ID of a block by name; throws for unknown names (for code that refers to shaped blocks). */
export function blockId(name: string): number {
  const d = blockByName(name);
  if (!d) throw new Error(`Unknown block ${name}`);
  return d.id;
}

/** Base block of a variant family (the block itself if it is not a variant). */
export function baseBlock(id: number): number {
  return DEFS[id]?.variantOf ?? id;
}

/** `[base, ...variants]` of a family, in ID order (just `[id]` for an ordinary block). */
export function blockVariants(id: number): number[] {
  const base = baseBlock(id);
  const out = [base];
  for (let i = base + 1; i < DEFS.length && DEFS[i]!.variantOf === base; i++) out.push(i);
  return out;
}

/** Block ID of a concrete colour. */
export function concreteBlock(colour: ConcreteColour): number {
  return BlockId.ConcreteWhite + CONCRETE_COLOURS.findIndex((c) => c.name === colour);
}
