// Loads the vendored mapcore WASM in a browser window or worker (Vite turns the URL below into an
// emitted asset in builds) and registers it with the shared generators.
import { registerMapcore, type MapcoreApi } from '@voxel/shared';
import init, { MapGen, MapPrepare, dem_tiles, package_version, prepare } from '../vendor/mapcore/mapcore_wasm.js';

let loading: Promise<MapcoreApi> | undefined;

export function loadMapcore(): Promise<MapcoreApi> {
  loading ??= (async () => {
    await init({ module_or_path: new URL('../vendor/mapcore/mapcore_wasm_bg.wasm', import.meta.url) });
    const api: MapcoreApi = { MapGen, MapPrepare, dem_tiles, prepare, package_version };
    registerMapcore(api);
    return api;
  })();
  return loading;
}
