/**
 * Player movement physics. Pure, deterministic and tick-based: the same `stepPlayer` runs on the
 * client (prediction) and, from Milestone 10, on the server (validation). No DOM, no globals.
 *
 * Coordinates: `x`/`z` are the centre of the player's footprint, `y` is the bottom of the feet.
 * The collision box is PLAYER_WIDTH wide (x and z) and PLAYER_HEIGHT tall.
 */
import { BLOCKS, BlockId } from '../world/blocks';
import { BLOCK_HAS_MODEL, MAX_BLOCK_BOXES, collisionBoxes } from '../world/models';

export const PLAYER_WIDTH = 0.6;
export const PLAYER_HALF_WIDTH = PLAYER_WIDTH / 2;
export const PLAYER_HEIGHT = 1.8;
/** Eye height above the feet. */
export const PLAYER_EYE_HEIGHT = 1.62;

/** Downward acceleration, blocks/s^2. */
export const GRAVITY = 32;
/** Maximum fall speed, blocks/s. */
export const TERMINAL_VELOCITY = 60;
/** Peak height of a jump from flat ground, in blocks. */
export const JUMP_HEIGHT = 1.25;
/** Initial upward speed of a jump; exact for the trapezoidal integration used below. */
export const JUMP_VELOCITY = Math.sqrt(2 * GRAVITY * JUMP_HEIGHT);

export const WALK_SPEED = 4.3;
export const SPRINT_SPEED = 5.6;
export const SNEAK_SPEED = 1.3;
export const FLY_SPEED = 10;
export const FLY_SPRINT_SPEED = 30;

/** Rate (1/s) at which horizontal velocity approaches the wanted velocity. Higher = snappier. */
export const GROUND_ACCEL = 20;
/** Air control with movement input. */
export const AIR_ACCEL = 4;
/** Air drag without movement input (keeps jump momentum). */
export const AIR_DRAG = 0.5;

export const WATER_GRAVITY = 8;
/** Fastest sink speed in water. */
export const WATER_TERMINAL = 3;
/** Rate (1/s) at which velocity is damped in water. */
export const WATER_DRAG = 3;
export const WATER_SPEED_FACTOR = 0.55;
/** Upward acceleration while holding jump in water, and the swim-up speed cap. */
export const SWIM_ACCEL = 18;
export const SWIM_UP_SPEED = 3.2;
/** Vertical speed given when swimming against a wall, so you can climb out onto a 1-block shore. */
export const WATER_EXIT_SPEED = 6.5;

/**
 * Highest ledge the player walks up without jumping (map worlds, phase D): enough for a slab or a
 * stair step, less than a full block, so terrain made of cubes plays exactly as before.
 */
export const STEP_HEIGHT = 0.6;

/** Small gap used to avoid counting touching faces as overlapping. */
const EPS = 1e-6;
/** How far below the feet we probe for ground when sneaking at an edge. */
const SNEAK_PROBE = 0.05;

export type BlockGetter = (x: number, y: number, z: number) => number;

export interface PlayerState {
  x: number;
  y: number;
  z: number;
  vx: number;
  vy: number;
  vz: number;
  onGround: boolean;
  inWater: boolean;
  /** Free flight (debug): no gravity, no collision. */
  flying: boolean;
}

/** One tick's worth of control input. Movement axes are in -1..1 relative to `yaw`. */
export interface PlayerInput {
  /** +1 forward, -1 back. */
  forward: number;
  /** +1 right, -1 left. */
  strafe: number;
  jump: boolean;
  sprint: boolean;
  /** Sneak on the ground / descend while flying. */
  sneak: boolean;
  /** Look yaw in radians; 0 faces -Z, positive turns toward +X. */
  yaw: number;
}

export function createPlayerState(x = 0, y = 0, z = 0): PlayerState {
  return { x, y, z, vx: 0, vy: 0, vz: 0, onGround: false, inWater: false, flying: false };
}

export function emptyInput(yaw = 0): PlayerInput {
  return { forward: 0, strafe: 0, jump: false, sprint: false, sneak: false, yaw };
}

/** Lookup table: 1 if the block collides with the player. */
const SOLID = Uint8Array.from(BLOCKS, (b) => (b.solid ? 1 : 0));

export function isSolidBlock(id: number): boolean {
  return SOLID[id] === 1;
}

/** Axis-aligned box. */
export interface Aabb {
  minX: number;
  minY: number;
  minZ: number;
  maxX: number;
  maxY: number;
  maxZ: number;
}

export function playerAabb(x: number, y: number, z: number, out?: Aabb): Aabb {
  const box = out ?? { minX: 0, minY: 0, minZ: 0, maxX: 0, maxY: 0, maxZ: 0 };
  box.minX = x - PLAYER_HALF_WIDTH;
  box.maxX = x + PLAYER_HALF_WIDTH;
  box.minY = y;
  box.maxY = y + PLAYER_HEIGHT;
  box.minZ = z - PLAYER_HALF_WIDTH;
  box.maxZ = z + PLAYER_HALF_WIDTH;
  return box;
}

/** Whether a player standing at feet (x, y, z) overlaps the unit cell (bx, by, bz). */
export function playerIntersectsBlock(x: number, y: number, z: number, bx: number, by: number, bz: number): boolean {
  return (
    x + PLAYER_HALF_WIDTH > bx + EPS &&
    x - PLAYER_HALF_WIDTH < bx + 1 - EPS &&
    y + PLAYER_HEIGHT > by + EPS &&
    y < by + 1 - EPS &&
    z + PLAYER_HALF_WIDTH > bz + EPS &&
    z - PLAYER_HALF_WIDTH < bz + 1 - EPS
  );
}

/** Integer cell range [lo, hi] overlapped by the open interval (min, max). */
function cellLo(min: number): number {
  return Math.floor(min + EPS);
}
function cellHi(max: number): number {
  return Math.ceil(max - EPS) - 1;
}

const cbuf = new Float64Array(6 * MAX_BLOCK_BOXES);

/** Whether world box `b` (at offset o in `cbuf`) overlaps `box` (touching faces do not count). */
function overlapsAt(o: number, box: Aabb): boolean {
  return (
    cbuf[o]! < box.maxX - EPS && cbuf[o + 3]! > box.minX + EPS &&
    cbuf[o + 1]! < box.maxY - EPS && cbuf[o + 4]! > box.minY + EPS &&
    cbuf[o + 2]! < box.maxZ - EPS && cbuf[o + 5]! > box.minZ + EPS
  );
}

/** True if any solid block (or part of a shaped one: slab, stairs, post) overlaps the box. */
export function boxHitsSolid(getBlock: BlockGetter, box: Aabb): boolean {
  const x1 = cellHi(box.maxX), y1 = cellHi(box.maxY), z1 = cellHi(box.maxZ);
  for (let y = cellLo(box.minY); y <= y1; y++)
    for (let z = cellLo(box.minZ); z <= z1; z++)
      for (let x = cellLo(box.minX); x <= x1; x++) {
        const id = getBlock(x, y, z);
        if (SOLID[id] !== 1) continue;
        if (!BLOCK_HAS_MODEL[id]) return true;
        const n = collisionBoxes(getBlock, x, y, z, id, cbuf);
        for (let i = 0; i < n; i++) if (overlapsAt(i * 6, box)) return true;
      }
  return false;
}

/** True if any block of `id` overlaps the box. */
export function boxTouches(getBlock: BlockGetter, box: Aabb, id: number): boolean {
  const x1 = cellHi(box.maxX), y1 = cellHi(box.maxY), z1 = cellHi(box.maxZ);
  for (let y = cellLo(box.minY); y <= y1; y++)
    for (let z = cellLo(box.minZ); z <= z1; z++)
      for (let x = cellLo(box.minX); x <= x1; x++) if (getBlock(x, y, z) === id) return true;
  return false;
}

type Axis = 0 | 1 | 2;

/**
 * Swept move of `box` along one axis by `d`, stopping at the first solid box the leading face
 * would enter: whole cells for cubes, the model boxes of shaped blocks (slabs, stairs, posts).
 * Boxes the player already overlaps are ignored, so a player clipped into a block can still move
 * out of it. Every cell along the path is checked, so there is no tunnelling at any speed.
 * Returns the distance actually moved and updates `box` in place.
 */
export function sweepAxis(getBlock: BlockGetter, box: Aabb, axis: Axis, d: number): number {
  if (d === 0) return 0;
  // Cross-section cells on the two other axes.
  let aLo: number, aHi: number, bLo: number, bHi: number;
  let min: number, max: number;
  if (axis === 0) {
    aLo = cellLo(box.minY); aHi = cellHi(box.maxY); bLo = cellLo(box.minZ); bHi = cellHi(box.maxZ);
    min = box.minX; max = box.maxX;
  } else if (axis === 1) {
    aLo = cellLo(box.minX); aHi = cellHi(box.maxX); bLo = cellLo(box.minZ); bHi = cellHi(box.maxZ);
    min = box.minY; max = box.maxY;
  } else {
    aLo = cellLo(box.minX); aHi = cellHi(box.maxX); bLo = cellLo(box.minY); bHi = cellHi(box.maxY);
    min = box.minZ; max = box.maxZ;
  }
  // The two other axes as indices into a world box [minX, minY, minZ, maxX, maxY, maxZ].
  const o1 = axis === 0 ? 1 : 0;
  const o2 = axis === 2 ? 1 : 2;
  const boxLo = [box.minX, box.minY, box.minZ];
  const boxHi = [box.maxX, box.maxY, box.maxZ];

  let moved = d;
  /** Considers one solid cell `c` along the axis (cube or shaped block) at cross cell (a, b). */
  const consider = (c: number, x: number, y: number, z: number, id: number): void => {
    if (!BLOCK_HAS_MODEL[id]) {
      if (d > 0 && c >= max - EPS) moved = Math.min(moved, Math.max(0, c - max));
      else if (d < 0 && c + 1 <= min + EPS) moved = Math.max(moved, Math.min(0, c + 1 - min));
      return;
    }
    const n = collisionBoxes(getBlock, x, y, z, id, cbuf);
    for (let i = 0; i < n; i++) {
      const o = i * 6;
      if (!(cbuf[o + o1]! < boxHi[o1]! - EPS && cbuf[o + 3 + o1]! > boxLo[o1]! + EPS)) continue;
      if (!(cbuf[o + o2]! < boxHi[o2]! - EPS && cbuf[o + 3 + o2]! > boxLo[o2]! + EPS)) continue;
      const lo = cbuf[o + axis]!;
      const hi = cbuf[o + 3 + axis]!;
      if (d > 0 && lo >= max - EPS) moved = Math.min(moved, Math.max(0, lo - max));
      else if (d < 0 && hi <= min + EPS) moved = Math.max(moved, Math.min(0, hi - min));
    }
  };

  // From the cell holding the leading face to the last cell the move reaches.
  const first = d > 0 ? Math.floor(max - EPS) : Math.ceil(min + EPS) - 1;
  const last = d > 0 ? Math.ceil(max + d) - 1 : Math.floor(min + d);
  const step = d > 0 ? 1 : -1;
  for (let c = first; d > 0 ? c <= last : c >= last; c += step) {
    // Once a cube stopped us, cells further along cannot stop us sooner.
    if (d > 0 ? c - max > moved : c + 1 - min < moved) break;
    for (let a = aLo; a <= aHi; a++) {
      for (let b = bLo; b <= bHi; b++) {
        const x = axis === 0 ? c : a;
        const y = axis === 0 ? a : axis === 1 ? c : b;
        const z = axis === 2 ? c : b;
        const id = getBlock(x, y, z);
        if (SOLID[id] === 1) consider(c, x, y, z, id);
      }
    }
  }
  if (axis === 0) { box.minX += moved; box.maxX += moved; }
  else if (axis === 1) { box.minY += moved; box.maxY += moved; }
  else { box.minZ += moved; box.maxZ += moved; }
  return moved;
}

/** 1 - e^(-rate*dt): fraction of the gap closed this tick by an exponential approach. */
function approach(rate: number, dt: number): number {
  return 1 - Math.exp(-rate * dt);
}

const tmpBox: Aabb = { minX: 0, minY: 0, minZ: 0, maxX: 0, maxY: 0, maxZ: 0 };
const probeBox: Aabb = { minX: 0, minY: 0, minZ: 0, maxX: 0, maxY: 0, maxZ: 0 };

/** Whether a player at feet (x, y, z) has solid ground within SNEAK_PROBE below. */
function hasSupport(getBlock: BlockGetter, x: number, y: number, z: number): boolean {
  playerAabb(x, y, z, probeBox);
  probeBox.maxY = probeBox.minY;
  probeBox.minY -= SNEAK_PROBE;
  return boxHitsSolid(getBlock, probeBox);
}

/** Whether any water overlaps the player's body. */
export function isPlayerInWater(getBlock: BlockGetter, x: number, y: number, z: number): boolean {
  playerAabb(x, y, z, probeBox);
  // Only the lower body counts, so standing at a shoreline with water at foot level still swims.
  probeBox.maxY = probeBox.minY + 1.0;
  return boxTouches(getBlock, probeBox, BlockId.Water);
}

/**
 * Advances the player by one tick of `dt` seconds. Mutates and returns `state`.
 * Order: velocity update (input, gravity, drag) then collision, Y first, then X, then Z.
 */
export function stepPlayer(state: PlayerState, input: PlayerInput, getBlock: BlockGetter, dt: number): PlayerState {
  // Wanted horizontal direction from input, rotated by yaw (yaw 0 faces -Z).
  let fwd = input.forward;
  let str = input.strafe;
  const len = Math.hypot(fwd, str);
  if (len > 1) {
    fwd /= len;
    str /= len;
  }
  const sin = Math.sin(input.yaw);
  const cos = Math.cos(input.yaw);
  const dirX = sin * fwd + cos * str;
  const dirZ = -cos * fwd + sin * str;
  const moving = len > 0;

  if (state.flying) {
    const speed = input.sprint ? FLY_SPRINT_SPEED : FLY_SPEED;
    const up = (input.jump ? 1 : 0) - (input.sneak ? 1 : 0);
    const k = approach(GROUND_ACCEL, dt);
    state.vx += (dirX * speed - state.vx) * k;
    state.vz += (dirZ * speed - state.vz) * k;
    state.vy += (up * speed - state.vy) * k;
    state.x += state.vx * dt;
    state.y += state.vy * dt;
    state.z += state.vz * dt;
    state.onGround = false;
    state.inWater = isPlayerInWater(getBlock, state.x, state.y, state.z);
    return state;
  }

  const inWater = isPlayerInWater(getBlock, state.x, state.y, state.z);
  state.inWater = inWater;
  const sneaking = input.sneak && state.onGround && !inWater;

  // Horizontal velocity: approach the wanted velocity (acceleration and friction in one).
  let speed = input.sprint && input.forward > 0 && !input.sneak ? SPRINT_SPEED : WALK_SPEED;
  if (sneaking) speed = SNEAK_SPEED;
  if (inWater) speed *= WATER_SPEED_FACTOR;
  const rate = inWater ? GROUND_ACCEL * 0.5 : state.onGround ? GROUND_ACCEL : moving ? AIR_ACCEL : AIR_DRAG;
  const kh = approach(rate, dt);
  state.vx += (dirX * speed - state.vx) * kh;
  state.vz += (dirZ * speed - state.vz) * kh;

  // Vertical velocity. Positions use the average of old and new velocity (trapezoidal rule), which
  // is exact under constant gravity, so jump height does not depend on the tick rate.
  let vy0 = state.vy;
  if (inWater) {
    state.vy -= WATER_GRAVITY * dt;
    state.vy *= 1 - approach(WATER_DRAG, dt);
    if (input.jump) state.vy = Math.min(SWIM_UP_SPEED, state.vy + SWIM_ACCEL * dt);
    if (state.vy < -WATER_TERMINAL) state.vy = -WATER_TERMINAL;
  } else {
    if (input.jump && state.onGround) vy0 = JUMP_VELOCITY;
    state.vy = vy0 - GRAVITY * dt;
    if (state.vy < -TERMINAL_VELOCITY) state.vy = -TERMINAL_VELOCITY;
  }
  const dy = (vy0 + state.vy) * 0.5 * dt;

  const box = playerAabb(state.x, state.y, state.z, tmpBox);

  // Y.
  const movedY = sweepAxis(getBlock, box, 1, dy);
  const hitY = movedY !== dy;
  state.onGround = hitY && dy < 0;
  if (hitY) state.vy = 0;

  // X then Z. While sneaking on the ground, refuse horizontal moves that would leave no support.
  const before = { ...box };
  const dx = state.vx * dt;
  let movedX = sweepAxis(getBlock, box, 0, dx);
  if (sneaking && state.onGround && movedX !== 0 && !hasSupport(getBlock, (box.minX + box.maxX) / 2, box.minY, (box.minZ + box.maxZ) / 2)) {
    box.minX -= movedX;
    box.maxX -= movedX;
    movedX = 0;
  }
  const dz = state.vz * dt;
  let movedZ = sweepAxis(getBlock, box, 2, dz);
  if (sneaking && state.onGround && movedZ !== 0 && !hasSupport(getBlock, (box.minX + box.maxX) / 2, box.minY, (box.minZ + box.maxZ) / 2)) {
    box.minZ -= movedZ;
    box.maxZ -= movedZ;
    movedZ = 0;
  }

  // Blocked on the ground: try again lifted by STEP_HEIGHT (walk up slabs and stairs), and keep
  // that only if it gets further. A full block is always taller than the step, so cube terrain
  // never takes this path.
  if ((movedX !== dx || movedZ !== dz) && state.onGround && !inWater && !sneaking) {
    const alt = { ...before };
    const up = sweepAxis(getBlock, alt, 1, STEP_HEIGHT);
    const ax = sweepAxis(getBlock, alt, 0, dx);
    const az = sweepAxis(getBlock, alt, 2, dz);
    sweepAxis(getBlock, alt, 1, -up);
    if (up > 0 && ax * ax + az * az > movedX * movedX + movedZ * movedZ + 1e-12) {
      Object.assign(box, alt);
      movedX = ax;
      movedZ = az;
    }
  }

  let hitHorizontal = false;
  if (movedX !== dx) {
    state.vx = 0;
    hitHorizontal = true;
  }
  if (movedZ !== dz) {
    state.vz = 0;
    hitHorizontal = true;
  }

  // Swimming into a bank: hop up so the player can climb out.
  if (inWater && input.jump && hitHorizontal) state.vy = Math.max(state.vy, WATER_EXIT_SPEED);

  state.x = (box.minX + box.maxX) / 2;
  state.y = box.minY;
  state.z = (box.minZ + box.maxZ) / 2;
  return state;
}
