import { mulberry32 } from '../math/random';
import { BlockId } from '../world/blocks';
import { CHUNK_SIZE, Chunk, MAX_Y, MIN_Y, blockIndex } from '../world/chunk';
import { SimplexNoise, fbm2, hashInts } from './noise';

/**
 * Infinite terrain generator. Everything is a pure function of (seed, world coordinates), so a
 * chunk can be generated alone (in a worker or on the server) without its neighbours, and
 * features that cross chunk borders (trees) come out identical on both sides.
 */

/** Highest water block. Oceans and lakes are water from the floor up to and including this y. */
export const SEA_LEVEL = 62;
/** Mountain columns at or above this height get bare stone tops. */
export const STONE_LINE = 100;
/** Highest y a cave can reach down to; y below this is never carved (bedrock zone). */
const CAVE_MIN_Y = 4;
/**
 * Height limits frozen at the old 256-block world (phase C raised the world to y -64..319): seeds
 * from before keep generating exactly the same terrain above y 0, next to their saved chunks.
 */
const LEGACY_HEIGHT = 256;

export const Biome = {
  Ocean: 'ocean',
  Beach: 'beach',
  Plains: 'plains',
  Forest: 'forest',
  Desert: 'desert',
  Mountains: 'mountains',
} as const;
export type Biome = (typeof Biome)[keyof typeof Biome];

export interface ColumnSample {
  /** y of the top solid block before caves and trees. */
  height: number;
  biome: Biome;
}

/** A tree whose trunk starts at world (x, y, z) (the block above the ground). */
export interface Tree {
  x: number;
  y: number;
  z: number;
  /** Trunk height in blocks. */
  trunk: number;
  /** Random bits used to trim canopy corners. */
  trim: number;
}

export interface GenerateOptions {
  caves?: boolean;
  ores?: boolean;
  trees?: boolean;
}

/** Salts that derive independent noise fields / RNG streams from the one world seed. */
const Salt = {
  Continental: 1,
  Detail: 2,
  Hills: 3,
  Ridge: 4,
  Temperature: 5,
  Moisture: 6,
  CaveA: 7,
  CaveB: 8,
  Cavern: 9,
  Bedrock: 10,
  Ores: 11,
  DeepOres: 12,
  Trees: 12,
} as const;

/** Tree placement attempts per chunk; each succeeds with its column biome's probability. */
const TREE_ATTEMPTS = 10;
const TREE_CHANCE: Record<Biome, number> = {
  ocean: 0,
  beach: 0,
  desert: 0,
  plains: 0.04,
  forest: 0.6,
  mountains: 0.08,
};
/** Max horizontal reach of a tree canopy from its trunk. */
export const TREE_RADIUS = 2;

interface OreSpec {
  id: number;
  veins: number;
  minY: number;
  maxY: number;
  minSize: number;
  maxSize: number;
}
const ORES: readonly OreSpec[] = [
  { id: BlockId.CoalOre, veins: 16, minY: 5, maxY: 128, minSize: 6, maxSize: 14 },
  { id: BlockId.IronOre, veins: 8, minY: 5, maxY: 64, minSize: 4, maxSize: 9 },
];
/** Veins in the deep layer (y -60..-1), richer in iron. */
const DEEP_ORES: readonly OreSpec[] = [
  { id: BlockId.CoalOre, veins: 6, minY: -60, maxY: -1, minSize: 6, maxSize: 12 },
  { id: BlockId.IronOre, veins: 10, minY: -60, maxY: -1, minSize: 4, maxSize: 9 },
];

/** Surface layering for one column: `top` at the surface, then `filler`, then `under`, then stone. */
interface Layers {
  top: number;
  filler: number;
  fillerDepth: number;
  under: number;
  underDepth: number;
}
const L = (top: number, filler: number, fillerDepth: number, under: number = BlockId.Stone, underDepth = 0): Layers => ({
  top,
  filler,
  fillerDepth,
  under,
  underDepth,
});
const LAYERS_GRASS = L(BlockId.Grass, BlockId.Dirt, 3);
const LAYERS_DESERT = L(BlockId.Sand, BlockId.Sand, 3, BlockId.Sandstone, 4);
const LAYERS_BEACH = L(BlockId.Sand, BlockId.Sand, 3, BlockId.Sandstone, 2);
const LAYERS_SEABED_SHALLOW = L(BlockId.Sand, BlockId.Sand, 3);
const LAYERS_SEABED_DEEP = L(BlockId.Dirt, BlockId.Dirt, 2);
const LAYERS_STONE = L(BlockId.Stone, BlockId.Stone, 0);

function layersFor(biome: Biome, height: number): Layers {
  switch (biome) {
    case Biome.Ocean:
      return height >= SEA_LEVEL - 6 ? LAYERS_SEABED_SHALLOW : LAYERS_SEABED_DEEP;
    case Biome.Beach:
      return LAYERS_BEACH;
    case Biome.Desert:
      return LAYERS_DESERT;
    case Biome.Mountains:
      return height >= STONE_LINE ? LAYERS_STONE : LAYERS_GRASS;
    default:
      return LAYERS_GRASS;
  }
}

function smoothstep(e0: number, e1: number, x: number): number {
  const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
}

/** Visits every block of a tree: logs first, then leaves. Coordinates are world coordinates. */
export function forEachTreeBlock(tree: Tree, visit: (x: number, y: number, z: number, id: number) => void): void {
  const { x, y, z, trunk, trim } = tree;
  for (let i = 0; i < trunk; i++) visit(x, y + i, z, BlockId.Log);
  const top = y + trunk - 1;
  for (let dy = -2; dy <= 1; dy++) {
    const r = dy <= -1 ? 2 : 1;
    for (let dz = -r; dz <= r; dz++) {
      for (let dx = -r; dx <= r; dx++) {
        if (dx === 0 && dz === 0 && dy <= 0) continue; // trunk
        const corner = Math.abs(dx) === r && Math.abs(dz) === r;
        if (corner) {
          if (r === 1 && dy === 1) continue; // plus-shaped cap
          if (r === 2) {
            const bit = (dy + 2) * 4 + (dx > 0 ? 1 : 0) + (dz > 0 ? 2 : 0);
            if ((trim >> bit) & 1) continue;
          }
        }
        visit(x + dx, top + dy, z + dz, BlockId.Leaves);
      }
    }
  }
}

/** All blocks of a tree as [x, y, z, id] (allocates; for tests and tools). */
export function treeBlocks(tree: Tree): [number, number, number, number][] {
  const out: [number, number, number, number][] = [];
  forEachTreeBlock(tree, (x, y, z, id) => out.push([x, y, z, id]));
  return out;
}

export class TerrainGenerator {
  readonly seed: number;
  private readonly continental: SimplexNoise;
  private readonly detail: SimplexNoise;
  private readonly hills: SimplexNoise;
  private readonly ridge: SimplexNoise;
  private readonly temperature: SimplexNoise;
  private readonly moisture: SimplexNoise;
  private readonly caveA: SimplexNoise;
  private readonly caveB: SimplexNoise;
  private readonly cavern: SimplexNoise;
  /** Results of the last `shape` call (avoids allocating per column). */
  private shapeCoast = 0;
  private shapeMountain = 0;
  private readonly treeCache = new Map<string, Tree[]>();

  constructor(seed: number) {
    this.seed = seed >>> 0;
    const n = (salt: number) => new SimplexNoise(hashInts(this.seed, salt));
    this.continental = n(Salt.Continental);
    this.detail = n(Salt.Detail);
    this.hills = n(Salt.Hills);
    this.ridge = n(Salt.Ridge);
    this.temperature = n(Salt.Temperature);
    this.moisture = n(Salt.Moisture);
    this.caveA = n(Salt.CaveA);
    this.caveB = n(Salt.CaveB);
    this.cavern = n(Salt.Cavern);
  }

  /** Surface height (before caves/trees). Also leaves coast/mountain factors in shape* fields. */
  private shape(wx: number, wz: number): number {
    // Continentalness: below 0 is ocean, above is land.
    const c = fbm2(this.continental, wx * 0.0014, wz * 0.0014, 5) * 1.5 + 0.2;
    const land = smoothstep(-0.02, 0.2, c);
    const base = c < 0 ? SEA_LEVEL + c * 45 : SEA_LEVEL + 0.5 + c * 18;
    const detail = fbm2(this.detail, wx / 70, wz / 70, 4) * (2 + 6 * land);
    const mountain = smoothstep(0.1, 0.45, fbm2(this.hills, wx / 380, wz / 380, 3)) * land;
    let lift = 0;
    if (mountain > 0) {
      const r = 1 - Math.abs(fbm2(this.ridge, wx / 150, wz / 150, 4));
      lift = mountain * r * r * 75;
    }
    this.shapeCoast = c;
    this.shapeMountain = mountain;
    const h = Math.round(base + detail + lift);
    return h < 6 ? 6 : h > LEGACY_HEIGHT - 30 ? LEGACY_HEIGHT - 30 : h;
  }

  /** Height of the top terrain block at world column (wx, wz), ignoring caves and trees. */
  surfaceHeight(wx: number, wz: number): number {
    return this.shape(wx, wz);
  }

  /** Height and biome of a world column. */
  sampleColumn(wx: number, wz: number, out: ColumnSample = { height: 0, biome: Biome.Plains }): ColumnSample {
    const h = this.shape(wx, wz);
    out.height = h;
    out.biome = this.classify(wx, wz, h, this.shapeCoast, this.shapeMountain);
    return out;
  }

  biomeAt(wx: number, wz: number): Biome {
    return this.sampleColumn(Math.floor(wx), Math.floor(wz)).biome;
  }

  private classify(wx: number, wz: number, h: number, coast: number, mountain: number): Biome {
    if (h < SEA_LEVEL) return Biome.Ocean;
    if (h <= SEA_LEVEL + 2 && coast < 0.12) return Biome.Beach;
    if (mountain > 0.5) return Biome.Mountains;
    const temp = fbm2(this.temperature, wx / 520, wz / 520, 2);
    const moist = fbm2(this.moisture, wx / 430, wz / 430, 2);
    if (temp > 0.15 && moist < 0.05) return Biome.Desert;
    if (moist > 0.05) return Biome.Forest;
    return Biome.Plains;
  }

  /**
   * Highest y caves may carve in a column of height `h`. Columns next to (or holding) water stop
   * carving two blocks below the lowest neighbouring floor, so a cave can never touch water.
   */
  carveLimit(wx: number, wz: number, h: number): number {
    let min = h;
    let wet = h < SEA_LEVEL;
    for (let dz = -1; dz <= 1; dz++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dz === 0) continue;
        const nh = this.shape(wx + dx, wz + dz);
        if (nh < min) min = nh;
        if (nh < SEA_LEVEL) wet = true;
      }
    }
    return wet ? min - 2 : h;
  }

  /** Whether the cave noise carves (wx, y, wz). Does not apply `carveLimit`. */
  isCave(wx: number, y: number, wz: number): boolean {
    if (y < CAVE_MIN_Y) return false;
    // Spaghetti tunnels: where two independent noise fields are both near zero.
    const a = this.caveA.noise3(wx / 42, y / 26, wz / 42);
    if (a > -0.09 && a < 0.09) {
      const b = this.caveB.noise3(wx / 42, y / 26, wz / 42);
      if (a * a + b * b < 0.008) return true;
    }
    return y < 48 && this.cavernAt(wx, y, wz);
  }

  /** Larger open caverns deep underground. */
  private cavernAt(wx: number, y: number, wz: number): boolean {
    const c = this.cavern.noise3(wx / 64, y / 28, wz / 64);
    const threshold = 0.64 + (y > 32 ? (y - 32) * 0.025 : 0);
    return c > threshold;
  }

  /** Trees whose trunks are in chunk (cx, cz). Deterministic; may extend into neighbour chunks. */
  treesInChunk(cx: number, cz: number): Tree[] {
    const cacheKey = `${cx},${cz}`;
    const cached = this.treeCache.get(cacheKey);
    if (cached) return cached;

    const rand = mulberry32(hashInts(this.seed, Salt.Trees, cx, cz));
    const trees: Tree[] = [];
    const col: ColumnSample = { height: 0, biome: Biome.Plains };
    for (let n = 0; n < TREE_ATTEMPTS; n++) {
      // Always consume the same number of random values per attempt.
      const lx = Math.floor(rand() * CHUNK_SIZE);
      const lz = Math.floor(rand() * CHUNK_SIZE);
      const roll = rand();
      const trunk = 4 + Math.floor(rand() * 3);
      const trim = Math.floor(rand() * 0x10000);
      const wx = cx * CHUNK_SIZE + lx;
      const wz = cz * CHUNK_SIZE + lz;
      this.sampleColumn(wx, wz, col);
      if (roll >= TREE_CHANCE[col.biome]) continue;
      const h = col.height;
      if (h <= SEA_LEVEL || h >= STONE_LINE || h + trunk + 3 >= LEGACY_HEIGHT) continue;
      if (trees.some((t) => Math.abs(t.x - wx) <= 2 && Math.abs(t.z - wz) <= 2)) continue;
      const limit = this.carveLimit(wx, wz, h);
      if (h <= limit && (this.isCave(wx, h, wz) || this.isCave(wx, h - 1, wz))) continue; // ground carved away
      trees.push({ x: wx, y: h + 1, z: wz, trunk, trim });
    }

    if (this.treeCache.size >= 512) this.treeCache.clear();
    this.treeCache.set(cacheKey, trees);
    return trees;
  }

  /** Generates chunk (cx, cz). Pass `into` to reuse a chunk object (its blocks are overwritten). */
  generateChunk(cx: number, cz: number, options: GenerateOptions = {}, into?: Chunk): Chunk {
    const { caves = true, ores = true, trees = true } = options;
    const chunk = into ?? new Chunk(cx, cz);
    const blocks = chunk.blocks;
    blocks.fill(BlockId.Air);
    const x0 = cx * CHUNK_SIZE;
    const z0 = cz * CHUNK_SIZE;

    // Heights for the chunk plus a 1-column border (needed for the cave/water rule).
    const P = CHUNK_SIZE + 2;
    const heights = new Int32Array(P * P);
    for (let pz = 0; pz < P; pz++) for (let px = 0; px < P; px++) heights[pz * P + px] = this.shape(x0 + px - 1, z0 + pz - 1);

    const col: ColumnSample = { height: 0, biome: Biome.Plains };
    for (let lz = 0; lz < CHUNK_SIZE; lz++) {
      for (let lx = 0; lx < CHUNK_SIZE; lx++) {
        const wx = x0 + lx;
        const wz = z0 + lz;
        this.sampleColumn(wx, wz, col);
        const h = col.height;
        const layers = layersFor(col.biome, h);

        // Solid column with surface layers.
        const fillerEnd = h - layers.fillerDepth; // filler occupies (fillerEnd, h)
        const underEnd = fillerEnd - layers.underDepth;
        for (let y = MIN_Y; y <= h; y++) {
          let id: number;
          if (y === h) id = layers.top;
          else if (y > fillerEnd) id = layers.filler;
          else if (y > underEnd) id = layers.under;
          else id = BlockId.Stone;
          blocks[blockIndex(lx, y, lz)] = id;
        }
        // Bedrock: solid at the world floor (MIN_Y), increasingly patchy up to 3 blocks above it.
        blocks[blockIndex(lx, MIN_Y, lz)] = BlockId.Bedrock;
        for (let k = 1; k <= 3; k++) {
          if ((hashInts(this.seed, Salt.Bedrock, wx, k, wz) & 3) < 4 - k) blocks[blockIndex(lx, MIN_Y + k, lz)] = BlockId.Bedrock;
        }
        // Water.
        for (let y = h + 1; y <= SEA_LEVEL; y++) blocks[blockIndex(lx, y, lz)] = BlockId.Water;

        // Caves.
        if (caves) {
          let limit = h;
          let wet = h < SEA_LEVEL;
          for (let dz = 0; dz <= 2; dz++) {
            for (let dx = 0; dx <= 2; dx++) {
              const nh = heights[(lz + dz) * P + (lx + dx)]!;
              if (nh < limit) limit = nh;
              if (nh < SEA_LEVEL) wet = true;
            }
          }
          limit = wet ? limit - 2 : h;
          for (let y = CAVE_MIN_Y; y <= limit; y++) {
            const i = blockIndex(lx, y, lz);
            if (blocks[i] === BlockId.Bedrock) continue;
            if (this.isCave(wx, y, wz)) blocks[i] = BlockId.Air;
          }
        }
      }
    }

    if (ores) {
      this.placeOres(chunk);
      this.placeDeepOres(chunk);
    }
    if (trees) this.placeTrees(chunk);
    chunk.recount();
    return chunk;
  }

  private placeOres(chunk: Chunk): void {
    const blocks = chunk.blocks;
    const rand = mulberry32(hashInts(this.seed, Salt.Ores, chunk.cx, chunk.cz));
    for (const ore of ORES) {
      for (let v = 0; v < ore.veins; v++) {
        let x = Math.floor(rand() * CHUNK_SIZE);
        let y = ore.minY + Math.floor(rand() * (ore.maxY - ore.minY));
        let z = Math.floor(rand() * CHUNK_SIZE);
        const size = ore.minSize + Math.floor(rand() * (ore.maxSize - ore.minSize + 1));
        for (let s = 0; s < size; s++) {
          const i = blockIndex(x, y, z);
          if (blocks[i] === BlockId.Stone) blocks[i] = ore.id;
          // Random walk, clamped to the chunk so veins never need neighbour data.
          const step = Math.floor(rand() * 6);
          const dir = step & 1 ? 1 : -1;
          if (step < 2) x = Math.min(CHUNK_SIZE - 1, Math.max(0, x + dir));
          else if (step < 4) y = Math.min(LEGACY_HEIGHT - 1, Math.max(1, y + dir));
          else z = Math.min(CHUNK_SIZE - 1, Math.max(0, z + dir));
        }
      }
    }
  }

  /**
   * Ore veins in the deep layer below y 0 (phase C). A separate random stream, and veins stay below
   * y 0, so terrain above y 0 is unchanged for old seeds.
   */
  private placeDeepOres(chunk: Chunk): void {
    const blocks = chunk.blocks;
    const rand = mulberry32(hashInts(this.seed, Salt.DeepOres, chunk.cx, chunk.cz));
    for (const ore of DEEP_ORES) {
      for (let v = 0; v < ore.veins; v++) {
        let x = Math.floor(rand() * CHUNK_SIZE);
        let y = ore.minY + Math.floor(rand() * (ore.maxY - ore.minY));
        let z = Math.floor(rand() * CHUNK_SIZE);
        const size = ore.minSize + Math.floor(rand() * (ore.maxSize - ore.minSize + 1));
        for (let s = 0; s < size; s++) {
          const i = blockIndex(x, y, z);
          if (blocks[i] === BlockId.Stone) blocks[i] = ore.id;
          const step = Math.floor(rand() * 6);
          const dir = step & 1 ? 1 : -1;
          if (step < 2) x = Math.min(CHUNK_SIZE - 1, Math.max(0, x + dir));
          else if (step < 4) y = Math.min(-1, Math.max(MIN_Y + 4, y + dir));
          else z = Math.min(CHUNK_SIZE - 1, Math.max(0, z + dir));
        }
      }
    }
  }

  /**
   * Writes the parts of every tree from this chunk and its 8 neighbours that fall inside this
   * chunk. Logs replace air or leaves; leaves only fill air. The result is independent of the
   * order trees are visited in, so overlapping trees agree on both sides of a border.
   */
  private placeTrees(chunk: Chunk): void {
    const blocks = chunk.blocks;
    const x0 = chunk.cx * CHUNK_SIZE;
    const z0 = chunk.cz * CHUNK_SIZE;
    const visit = (x: number, y: number, z: number, id: number): void => {
      const lx = x - x0;
      const lz = z - z0;
      if (lx < 0 || lx >= CHUNK_SIZE || lz < 0 || lz >= CHUNK_SIZE || y < MIN_Y || y > MAX_Y) return;
      const i = blockIndex(lx, y, lz);
      const cur = blocks[i];
      if (cur === BlockId.Air || (id === BlockId.Log && cur === BlockId.Leaves)) blocks[i] = id;
    };
    for (let dz = -1; dz <= 1; dz++) {
      for (let dx = -1; dx <= 1; dx++) {
        for (const tree of this.treesInChunk(chunk.cx + dx, chunk.cz + dz)) {
          // Skip trees that can't reach this chunk.
          if (tree.x + TREE_RADIUS < x0 || tree.x - TREE_RADIUS >= x0 + CHUNK_SIZE) continue;
          if (tree.z + TREE_RADIUS < z0 || tree.z - TREE_RADIUS >= z0 + CHUNK_SIZE) continue;
          forEachTreeBlock(tree, visit);
        }
      }
    }
  }
}
