import { BlockId } from './blocks';

/** Horizontal chunk edge length (x and z). */
export const CHUNK_SIZE = 16;
/**
 * World height (map worlds, phase C): the Minecraft range, y -64..319 (384 blocks). Every API takes
 * WORLD y; chunk arrays store layer `y - MIN_Y`. Worlds made before this were y 0..255: their saved
 * chunks are padded on load (see storage/chunkCodec.ts).
 */
export const MIN_Y = -64;
/** Vertical chunk height in blocks. */
export const CHUNK_HEIGHT = 384;
/** Highest block y. */
export const MAX_Y = MIN_Y + CHUNK_HEIGHT - 1; // 319
/** Edge length of a cubic section. */
export const SECTION_SIZE = 16;
export const SECTION_COUNT = CHUNK_HEIGHT / SECTION_SIZE; // 24
export const SECTION_VOLUME = SECTION_SIZE * SECTION_SIZE * SECTION_SIZE; // 4096
export const CHUNK_VOLUME = CHUNK_SIZE * CHUNK_SIZE * CHUNK_HEIGHT; // 98304

/** Height and volume of chunks saved before phase C (y 0..255). */
export const LEGACY_CHUNK_HEIGHT = 256;
export const LEGACY_CHUNK_VOLUME = CHUNK_SIZE * CHUNK_SIZE * LEGACY_CHUNK_HEIGHT; // 65536

/**
 * Index of block (x, z local 0..15, y WORLD y in MIN_Y..MAX_Y) in a chunk's arrays.
 * Layout is y-major (`(y - MIN_Y) * 256 + z * 16 + x`), so section `sy` is the contiguous range
 * `[sy * 4096, (sy + 1) * 4096)`.
 */
export function blockIndex(x: number, y: number, z: number): number {
  return ((y - MIN_Y) << 8) | (z << 4) | x;
}

/** Section index (0..SECTION_COUNT-1) of world y. */
export function sectionOf(y: number): number {
  return (y - MIN_Y) >> 4;
}

/** World y of the bottom of section `sy`. */
export function sectionBaseY(sy: number): number {
  return MIN_Y + sy * SECTION_SIZE;
}

export function inChunkBounds(x: number, y: number, z: number): boolean {
  return x >= 0 && x < CHUNK_SIZE && z >= 0 && z < CHUNK_SIZE && y >= MIN_Y && y <= MAX_Y;
}

/** Source of section versions; never 0. */
let nextVersion = 1;

/** One 16x16x384 column of blocks (y -64..319), split into 24 cubic sections for meshing. */
export class Chunk {
  /** Block IDs, see `blockIndex`. */
  readonly blocks: Uint16Array;
  /**
   * Light per block, indexed like `blocks`: high nibble sky light, low nibble block light (each
   * 0..15). See `lighting.ts` for how it is computed and kept up to date.
   */
  readonly light: Uint8Array;
  /** Non-air block count per section; 0 means the section is empty. */
  readonly sectionBlockCount = new Uint16Array(SECTION_COUNT);
  /** 1 when the section's mesh is out of date. */
  readonly sectionDirty = new Uint8Array(SECTION_COUNT);
  /**
   * Set to a fresh value (from a counter shared by all chunks in this thread) every time a section
   * is marked dirty, including by neighbour changes. A mesh built from version N is stale once this
   * differs from N. Global uniqueness means an unloaded-then-reloaded chunk can't alias an old job.
   */
  readonly sectionVersion = new Uint32Array(SECTION_COUNT);
  private dirtyCount = 0;

  /**
   * @param blocks Optional existing block data (e.g. transferred from a generator worker), taken
   *   over without copying. Call `recount()` after passing it so section counts are correct.
   * @param light Optional existing light data (same layout), taken over without copying.
   */
  constructor(
    readonly cx: number,
    readonly cz: number,
    blocks?: Uint16Array,
    light?: Uint8Array,
  ) {
    if (blocks && blocks.length !== CHUNK_VOLUME) throw new Error(`Chunk blocks must have ${CHUNK_VOLUME} entries`);
    if (light && light.length !== CHUNK_VOLUME) throw new Error(`Chunk light must have ${CHUNK_VOLUME} entries`);
    this.blocks = blocks ?? new Uint16Array(CHUNK_VOLUME);
    this.light = light ?? new Uint8Array(CHUNK_VOLUME);
  }

  /** Sky light (0..15) at local coordinates. */
  getSkyLight(x: number, y: number, z: number): number {
    return this.light[blockIndex(x, y, z)]! >> 4;
  }

  /** Block light (0..15) at local coordinates. */
  getBlockLight(x: number, y: number, z: number): number {
    return this.light[blockIndex(x, y, z)]! & 15;
  }

  /** Sets sky light at local coordinates. Does not mark anything dirty (the light engine does). */
  setSkyLight(x: number, y: number, z: number, level: number): void {
    const i = blockIndex(x, y, z);
    this.light[i] = (this.light[i]! & 0x0f) | ((level & 15) << 4);
  }

  /** Sets block light at local coordinates. Does not mark anything dirty (the light engine does). */
  setBlockLight(x: number, y: number, z: number, level: number): void {
    const i = blockIndex(x, y, z);
    this.light[i] = (this.light[i]! & 0xf0) | (level & 15);
  }

  get(x: number, y: number, z: number): number {
    return this.blocks[blockIndex(x, y, z)]!;
  }

  /**
   * Sets a block by local coordinates. Updates section counts and marks the section (and the
   * vertically adjacent section when on its boundary) dirty. Returns false if nothing changed.
   * Horizontal neighbours in other chunks are handled by `World.setBlock`.
   */
  set(x: number, y: number, z: number, id: number): boolean {
    const i = blockIndex(x, y, z);
    const old = this.blocks[i]!;
    if (old === id) return false;
    this.blocks[i] = id;
    const sy = sectionOf(y);
    if (old === BlockId.Air) this.sectionBlockCount[sy]!++;
    else if (id === BlockId.Air) this.sectionBlockCount[sy]!--;
    this.markSectionDirty(sy);
    const ly = y & 15;
    if (ly === 0 && sy > 0) this.markSectionDirty(sy - 1);
    if (ly === 15 && sy < SECTION_COUNT - 1) this.markSectionDirty(sy + 1);
    return true;
  }

  /** Fills a box of local coordinates (inclusive min, exclusive max) quickly. Marks touched sections dirty. */
  fill(x0: number, y0: number, z0: number, x1: number, y1: number, z1: number, id: number): void {
    for (let y = y0; y < y1; y++) {
      for (let z = z0; z < z1; z++) {
        for (let x = x0; x < x1; x++) this.blocks[blockIndex(x, y, z)] = id;
      }
    }
    this.recount();
  }

  /** Recomputes all section counts and marks every section dirty (after bulk writes to `blocks`). */
  recount(): void {
    for (let sy = 0; sy < SECTION_COUNT; sy++) {
      let n = 0;
      const start = sy * SECTION_VOLUME;
      for (let i = start; i < start + SECTION_VOLUME; i++) if (this.blocks[i] !== BlockId.Air) n++;
      this.sectionBlockCount[sy] = n;
      this.markSectionDirty(sy);
    }
  }

  isSectionEmpty(sy: number): boolean {
    return this.sectionBlockCount[sy] === 0;
  }

  markSectionDirty(sy: number): void {
    if (!this.sectionDirty[sy]) {
      this.sectionDirty[sy] = 1;
      this.dirtyCount++;
    }
    this.sectionVersion[sy] = nextVersion;
    nextVersion = (nextVersion + 1) >>> 0 || 1;
  }

  markAllDirty(): void {
    for (let sy = 0; sy < SECTION_COUNT; sy++) this.markSectionDirty(sy);
  }

  clearSectionDirty(sy: number): void {
    if (this.sectionDirty[sy]) {
      this.sectionDirty[sy] = 0;
      this.dirtyCount--;
    }
  }

  get hasDirtySections(): boolean {
    return this.dirtyCount > 0;
  }
}
