import { Chunk, computeChunkLight, createGenerator, generatorKey, type ChunkGenerator } from '@voxel/shared';
import type { GenRequest, GenResponse } from './genProtocol';

/**
 * The gen worker's work, without the worker (so tests can run it): generates the requested chunk
 * with the world's generator (or takes the blocks of a saved chunk) and lights it on its own. The
 * generator is created through the shared `createGenerator`, like the server's, and kept while
 * requests keep naming the same one. Map worlds need their MapPackage: `packages(id)` returns it
 * (the worker loads it from IndexedDB before running the job).
 */
export class GenJobRunner {
  private generator: ChunkGenerator | undefined;
  private key = '';

  constructor(private readonly packages: (id: string) => Uint8Array | undefined = () => undefined) {}

  run(req: GenRequest): GenResponse {
    const { job, seed, cx, cz, blocks } = req;
    const t0 = performance.now();
    let chunk: Chunk;
    if (blocks) {
      chunk = new Chunk(cx, cz, blocks);
    } else {
      const key = generatorKey(req);
      if (!this.generator || this.key !== key) {
        this.generator?.dispose?.();
        this.generator = createGenerator(req, req.mapPackageId === undefined ? undefined : this.packages(req.mapPackageId));
        this.key = key;
      }
      chunk = this.generator.generateChunk(cx, cz);
    }
    const t1 = performance.now();
    computeChunkLight(chunk);
    const t2 = performance.now();
    return {
      job,
      seed,
      cx,
      cz,
      blocks: chunk.blocks,
      light: chunk.light,
      ms: t1 - t0,
      lightMs: t2 - t1,
      fromSave: !!blocks,
    };
  }
}
