/**
 * Health, hunger, air and fall damage (Milestone 7). Pure state + functions; the game session
 * calls them every tick and applies the damage they report.
 *
 * Hunger model: activity adds "exhaustion"; every EXHAUSTION_PER_POINT of it removes one point of
 * saturation (a hidden buffer) or, once saturation is empty, one hunger point.
 */

export type GameMode = 'survival' | 'creative';

/** Accepts saved modes from older versions ('normal' became 'survival' in Milestone 7). */
export function normalizeGameMode(mode: unknown): GameMode {
  return mode === 'creative' ? 'creative' : 'survival';
}

export const MAX_HEALTH = 20;
export const MAX_HUNGER = 20;
/** Seconds of breath under water. */
export const MAX_AIR = 15;
export const START_SATURATION = 5;

/** Falls up to this many blocks are free; each further block costs 1 HP. */
export const SAFE_FALL_DISTANCE = 3;

export const EXHAUSTION_PER_POINT = 4;
export const EXHAUSTION_SPRINT_PER_BLOCK = 0.1;
export const EXHAUSTION_SWIM_PER_BLOCK = 0.015;
export const EXHAUSTION_JUMP = 0.05;
export const EXHAUSTION_SPRINT_JUMP = 0.2;
export const EXHAUSTION_BREAK_BLOCK = 0.005;
/** Slow drain over time even when idle. */
export const EXHAUSTION_PER_SECOND = 0.01;
/** Exhaustion added per healed HP. */
export const EXHAUSTION_PER_HEAL = 3;

/** Sprinting needs more than this much hunger. */
export const SPRINT_MIN_HUNGER = 6;
/** Natural regeneration needs at least this much hunger. */
export const REGEN_MIN_HUNGER = 18;
export const REGEN_INTERVAL = 4;
export const STARVE_INTERVAL = 4;
/** Starvation stops at this health (it hurts, but does not kill). */
export const STARVE_MIN_HEALTH = 1;
export const DROWN_INTERVAL = 1;
export const DROWN_DAMAGE = 2;
/** Air refills this many times faster than it drains. */
export const AIR_REFILL_RATE = 5;

export interface Vitals {
  health: number;
  hunger: number;
  saturation: number;
  exhaustion: number;
  /** Seconds of breath left. */
  air: number;
  /** Blocks fallen since last on ground / in water. */
  fallDistance: number;
  regenTimer: number;
  starveTimer: number;
  drownTimer: number;
}

export function createVitals(): Vitals {
  return {
    health: MAX_HEALTH,
    hunger: MAX_HUNGER,
    saturation: START_SATURATION,
    exhaustion: 0,
    air: MAX_AIR,
    fallDistance: 0,
    regenTimer: 0,
    starveTimer: 0,
    drownTimer: 0,
  };
}

export function resetVitals(v: Vitals): void {
  Object.assign(v, createVitals());
}

/** HP lost for landing after falling `distance` blocks. */
export function fallDamage(distance: number): number {
  return Math.max(0, Math.floor(distance - SAFE_FALL_DISTANCE + 1e-6));
}

/**
 * Tracks falling between two ticks and returns the damage on landing (0 otherwise).
 * Water and flying reset the fall, so landing in water never hurts.
 */
export function updateFall(v: Vitals, prevY: number, y: number, onGround: boolean, inWater: boolean, flying: boolean): number {
  if (flying || inWater) {
    v.fallDistance = 0;
    return 0;
  }
  if (y < prevY) v.fallDistance += prevY - y;
  if (!onGround) return 0;
  const dmg = fallDamage(v.fallDistance);
  v.fallDistance = 0;
  return dmg;
}

/** Adds exhaustion and converts whole units into lost saturation, then hunger. */
export function addExhaustion(v: Vitals, amount: number): void {
  v.exhaustion += amount;
  while (v.exhaustion >= EXHAUSTION_PER_POINT) {
    v.exhaustion -= EXHAUSTION_PER_POINT;
    if (v.saturation > 0) v.saturation = Math.max(0, v.saturation - 1);
    else v.hunger = Math.max(0, v.hunger - 1);
  }
}

export function canSprint(v: Vitals): boolean {
  return v.hunger > SPRINT_MIN_HUNGER;
}

/** Eats food: restores hunger, and saturation up to the hunger level. */
export function eat(v: Vitals, hunger: number, saturation: number): void {
  v.hunger = Math.min(MAX_HUNGER, v.hunger + hunger);
  v.saturation = Math.min(v.hunger, v.saturation + saturation);
}

export type DamageCause = 'fall' | 'drown' | 'starve' | 'void' | 'mob' | 'other';

export interface VitalsTickResult {
  /** Damage to apply this tick, by cause (0 = none). */
  drown: number;
  starve: number;
  /** HP healed this tick. */
  healed: number;
}

/**
 * Advances timers by `dt`: passive exhaustion, regeneration when well fed, starvation when empty,
 * and drowning while the head is under water. Healing is applied directly; damage is returned.
 */
export function tickVitals(v: Vitals, dt: number, headInWater: boolean): VitalsTickResult {
  const out: VitalsTickResult = { drown: 0, starve: 0, healed: 0 };
  addExhaustion(v, EXHAUSTION_PER_SECOND * dt);

  // Air.
  if (headInWater) {
    v.air = Math.max(0, v.air - dt);
    if (v.air <= 0) {
      v.drownTimer += dt;
      if (v.drownTimer >= DROWN_INTERVAL) {
        v.drownTimer -= DROWN_INTERVAL;
        out.drown = DROWN_DAMAGE;
      }
    } else {
      v.drownTimer = 0;
    }
  } else {
    v.air = Math.min(MAX_AIR, v.air + dt * AIR_REFILL_RATE);
    v.drownTimer = 0;
  }

  // Regeneration.
  if (v.hunger >= REGEN_MIN_HUNGER && v.health < MAX_HEALTH && v.health > 0) {
    v.regenTimer += dt;
    if (v.regenTimer >= REGEN_INTERVAL) {
      v.regenTimer -= REGEN_INTERVAL;
      v.health = Math.min(MAX_HEALTH, v.health + 1);
      out.healed = 1;
      addExhaustion(v, EXHAUSTION_PER_HEAL);
    }
  } else {
    v.regenTimer = 0;
  }

  // Starvation.
  if (v.hunger <= 0) {
    v.starveTimer += dt;
    if (v.starveTimer >= STARVE_INTERVAL) {
      v.starveTimer -= STARVE_INTERVAL;
      if (v.health > STARVE_MIN_HEALTH) out.starve = 1;
    }
  } else {
    v.starveTimer = 0;
  }
  return out;
}

/** Saved form of the vitals (timers are not saved). */
export interface SavedVitals {
  health: number;
  hunger: number;
  saturation: number;
  air: number;
}

export function vitalsToSaved(v: Vitals): SavedVitals {
  return { health: v.health, hunger: v.hunger, saturation: v.saturation, air: v.air };
}

export function vitalsFromSaved(s: Partial<SavedVitals> | undefined): Vitals {
  const v = createVitals();
  if (!s) return v;
  const num = (x: unknown, lo: number, hi: number, fallback: number): number => {
    const n = Number(x);
    return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : fallback;
  };
  v.health = num(s.health, 0, MAX_HEALTH, MAX_HEALTH);
  v.hunger = num(s.hunger, 0, MAX_HUNGER, MAX_HUNGER);
  v.saturation = num(s.saturation, 0, MAX_HUNGER, START_SATURATION);
  v.air = num(s.air, 0, MAX_AIR, MAX_AIR);
  return v;
}
