/**
 * Packed chunk-section vertex: two Uint32 words per vertex, read in the shader with
 * `vertexAttribIPointer(loc, 2, UNSIGNED_INT, 8, 0)` as a `uvec2`.
 *
 * word0: x[0..8] y[9..17] z[18..26] face[27..29] ao[30..31]
 * word1: sky[0..5] block[6..11] layer[12..21] u[22..26] v[27..31]
 *
 * x/y/z are section-local corner positions in SIXTEENTHS of a block, 0..256 (map worlds, phase D:
 * slabs, stairs, posts and rails need sub-block corners). u/v are texture coordinates in sixteenths
 * of one texture tile, 0..16 (culled meshing never spans more than one tile). `face` is a `Face`
 * value. `ao` is 0 (fully occluded corner) .. 3 (open). `sky` and `block` are the smoothed sky/block
 * light at the vertex in quarter steps: the stored value is `round(level * 4)`, 0..60, so averages
 * of 1, 2 or 4 samples are exact. `layer` is the texture-array layer (0..1023). The GLSL decoder
 * lives in the client's chunk shader and must match these shifts.
 */
export const VERTEX_WORDS = 2;
export const VERTEX_BYTES = VERTEX_WORDS * 4;

/** Steps per light level in the packed vertex light fields. */
export const LIGHT_SUBSTEPS = 4;

/** Vertex positions and texture coordinates are stored in 1/SUBVOXEL block units. */
export const SUBVOXEL = 16;

/** Face directions; the value is stored in the vertex. */
export const Face = {
  PosX: 0,
  NegX: 1,
  PosY: 2,
  NegY: 3,
  PosZ: 4,
  NegZ: 5,
  /** Diagonal quads of cross-shaped blocks (torches): no directional shading. */
  Cross: 6,
} as const;
export type Face = (typeof Face)[keyof typeof Face];

/** A vertex in block units (positions and u/v may be fractional, in steps of 1/SUBVOXEL). */
export interface UnpackedVertex {
  x: number;
  y: number;
  z: number;
  face: number;
  ao: number;
  /** Smoothed sky light 0..15 in steps of 1/LIGHT_SUBSTEPS. */
  sky: number;
  /** Smoothed block light 0..15 in steps of 1/LIGHT_SUBSTEPS. */
  block: number;
  layer: number;
  u: number;
  v: number;
}

/** Positions in sixteenths of a block (0..256 within a section). */
export function packWord0(x16: number, y16: number, z16: number, face: number, ao: number): number {
  return ((x16 & 511) | ((y16 & 511) << 9) | ((z16 & 511) << 18) | ((face & 7) << 27) | ((ao & 3) << 30)) >>> 0;
}

/**
 * `skyQ` / `blockQ` are already-quantised light values (level * LIGHT_SUBSTEPS, 0..63); `u16` /
 * `v16` are texture coordinates in sixteenths of a tile (0..16).
 */
export function packWord1(layer: number, u16: number, v16: number, skyQ = 60, blockQ = 0): number {
  return ((skyQ & 63) | ((blockQ & 63) << 6) | ((layer & 1023) << 12) | ((u16 & 31) << 22) | ((v16 & 31) << 27)) >>> 0;
}

function quantise(level: number): number {
  return Math.max(0, Math.min(63, Math.round(level * LIGHT_SUBSTEPS)));
}

/** Writes one vertex at vertex index `vi` of `out`. */
export function packVertex(out: Uint32Array, vi: number, vert: UnpackedVertex): void {
  const k = SUBVOXEL;
  out[vi * 2] = packWord0(Math.round(vert.x * k), Math.round(vert.y * k), Math.round(vert.z * k), vert.face, vert.ao);
  out[vi * 2 + 1] = packWord1(vert.layer, Math.round(vert.u * k), Math.round(vert.v * k), quantise(vert.sky), quantise(vert.block));
}

export function unpackVertex(data: Uint32Array, vi: number): UnpackedVertex {
  const w0 = data[vi * 2]!;
  const w1 = data[vi * 2 + 1]!;
  return {
    x: (w0 & 511) / SUBVOXEL,
    y: ((w0 >>> 9) & 511) / SUBVOXEL,
    z: ((w0 >>> 18) & 511) / SUBVOXEL,
    face: (w0 >>> 27) & 7,
    ao: (w0 >>> 30) & 3,
    sky: (w1 & 63) / LIGHT_SUBSTEPS,
    block: ((w1 >>> 6) & 63) / LIGHT_SUBSTEPS,
    layer: (w1 >>> 12) & 1023,
    u: ((w1 >>> 22) & 31) / SUBVOXEL,
    v: ((w1 >>> 27) & 31) / SUBVOXEL,
  };
}
