// Chunk generation worker: runs the world's shared generator (or takes the blocks of a saved
// chunk), lights the chunk on its own (no cross-chunk light yet; the main thread stitches borders
// when the chunk is added) and transfers the block and light arrays back. See `genJob.ts`.
//
// Map worlds (phase E): the first request naming a MapPackage loads mapcore's WASM and reads the
// package from IndexedDB (the main thread made sure it is current before the world started).
// Requests are handled strictly in order; a failure is rethrown asynchronously so the worker's
// error handler (WorkerSet) restarts it and retries the chunk.
import { loadMapcore } from '@voxel/mapgen/browser';
import { WorldStore } from '../storage/worldStore';
import { GenJobRunner } from './genJob';
import type { GenRequest } from './genProtocol';

const packages = new Map<string, Uint8Array>();
const runner = new GenJobRunner((id) => packages.get(id));
let queue: Promise<void> = Promise.resolve();

async function ensurePackage(id: string): Promise<void> {
  if (packages.has(id)) return;
  await loadMapcore();
  const store = await WorldStore.open();
  if (!store) throw new Error('IndexedDB is not available in the gen worker');
  try {
    const rec = await store.getMapPackage(id);
    if (!rec) throw new Error(`Map package ${id} is missing`);
    packages.set(id, rec.pkg);
  } finally {
    store.close();
  }
}

async function handle(req: GenRequest): Promise<void> {
  if (!req.blocks && req.generator === 'map' && req.mapPackageId !== undefined) await ensurePackage(req.mapPackageId);
  const res = runner.run(req);
  self.postMessage(res, { transfer: [res.blocks.buffer, res.light.buffer] });
}

self.onmessage = (e: MessageEvent<GenRequest>) => {
  const req = e.data;
  queue = queue.then(() => handle(req)).catch((err: unknown) => {
    setTimeout(() => {
      throw err;
    });
  });
};
