/** Minimal promise helpers over raw IndexedDB (no dependency). */

export const DB_NAME = 'voxel-sandbox';
/** 2 (map worlds, phase E): the `mapPackages` store. */
export const DB_VERSION = 2;
export const WORLDS_STORE = 'worlds';
export const CHUNKS_STORE = 'chunks';
/** Prepared MapPackages (plus the OSM data they came from), keyed by `WorldMeta.mapPackageId`. */
export const MAP_PACKAGES_STORE = 'mapPackages';

/** Resolves with the request's result, rejects with its error. */
export function req<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('IndexedDB request failed'));
  });
}

/** Resolves when the transaction commits, rejects if it errors or aborts. */
export function txDone(tx: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error ?? new Error('IndexedDB transaction failed'));
    tx.onabort = () => reject(tx.error ?? new Error('IndexedDB transaction aborted'));
  });
}

function upgrade(db: IDBDatabase, oldVersion: number): void {
  if (oldVersion < 1) {
    db.createObjectStore(WORLDS_STORE, { keyPath: 'id' });
    db.createObjectStore(CHUNKS_STORE, { keyPath: ['worldId', 'cx', 'cz'] });
  }
  if (oldVersion < 2) db.createObjectStore(MAP_PACKAGES_STORE, { keyPath: 'id' });
}

/**
 * Opens (and creates/upgrades) the database. Rejects if IndexedDB is missing, denied (some private
 * modes), or the open is blocked for longer than `timeoutMs`.
 */
export function openDatabase(factory: IDBFactory | undefined = globalThis.indexedDB, name = DB_NAME, timeoutMs = 5000): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (!factory) {
      reject(new Error('IndexedDB is not available'));
      return;
    }
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(new Error('Opening IndexedDB timed out (blocked by another tab?)'));
    }, timeoutMs);
    const finish = (fn: () => void): void => {
      clearTimeout(timer);
      if (settled) return;
      settled = true;
      fn();
    };
    let open: IDBOpenDBRequest;
    try {
      open = factory.open(name, DB_VERSION);
    } catch (err) {
      finish(() => reject(err instanceof Error ? err : new Error(String(err))));
      return;
    }
    open.onupgradeneeded = (e) => upgrade(open.result, e.oldVersion);
    open.onsuccess = () => {
      const db = open.result;
      if (settled) {
        db.close();
        return;
      }
      // Let a future version's upgrade in another tab proceed.
      db.onversionchange = () => db.close();
      finish(() => resolve(db));
    };
    open.onerror = () => finish(() => reject(open.error ?? new Error('IndexedDB open failed')));
    open.onblocked = () => console.warn('IndexedDB open is blocked by another tab; waiting...');
  });
}
