import { BlockId } from './blocks';
import { Chunk, MAX_Y, MIN_Y, SECTION_COUNT, SECTION_SIZE, blockIndex, sectionBaseY, sectionOf } from './chunk';

/** Edge length of the padded block copy fed to the mesher: one section plus a 1-block border. */
export const PADDED_SIZE = SECTION_SIZE + 2; // 18
export const PADDED_VOLUME = PADDED_SIZE * PADDED_SIZE * PADDED_SIZE; // 5832

/** Index into a padded 18^3 array. Coordinates are section-local in -1..16 (shifted by +1 internally). */
export function paddedIndex(x: number, y: number, z: number): number {
  return (y + 1) * PADDED_SIZE * PADDED_SIZE + (z + 1) * PADDED_SIZE + (x + 1);
}

const KEY_OFFSET = 32768;
const KEY_RANGE = 65536;

/** Unique numeric key for chunk (cx, cz). Valid for |cx|, |cz| < 32768. */
export function chunkKey(cx: number, cz: number): number {
  return (cx + KEY_OFFSET) * KEY_RANGE + (cz + KEY_OFFSET);
}

/** Unique numeric key for section (cx, sy, cz). */
export function sectionKey(cx: number, sy: number, cz: number): number {
  return chunkKey(cx, cz) * SECTION_COUNT + sy;
}

export function decodeSectionKey(key: number): { cx: number; sy: number; cz: number } {
  const sy = key % SECTION_COUNT;
  const ck = (key - sy) / SECTION_COUNT;
  const czo = ck % KEY_RANGE;
  return { cx: (ck - czo) / KEY_RANGE - KEY_OFFSET, sy, cz: czo - KEY_OFFSET };
}

/** Block ID used for everything below MIN_Y when building padded copies, so the world floor is culled. */
const BELOW_WORLD = BlockId.Stone;
/** Packed light (sky 15, block 0) above the world and in unloaded chunks. */
export const OPEN_SKY_LIGHT = 0xf0;

/** A set of loaded chunks keyed by chunk x/z, with world-coordinate block access. */
export class World {
  private readonly chunks = new Map<number, Chunk>();

  get chunkCount(): number {
    return this.chunks.size;
  }

  getChunk(cx: number, cz: number): Chunk | undefined {
    return this.chunks.get(chunkKey(cx, cz));
  }

  /**
   * Adds (or replaces) a chunk. Every section of it is marked dirty, and so are the sections of its
   * four horizontal neighbours, whose border faces may now be culled.
   */
  addChunk(chunk: Chunk): void {
    this.chunks.set(chunkKey(chunk.cx, chunk.cz), chunk);
    chunk.markAllDirty();
    this.getChunk(chunk.cx + 1, chunk.cz)?.markAllDirty();
    this.getChunk(chunk.cx - 1, chunk.cz)?.markAllDirty();
    this.getChunk(chunk.cx, chunk.cz + 1)?.markAllDirty();
    this.getChunk(chunk.cx, chunk.cz - 1)?.markAllDirty();
  }

  /** Removes a chunk; neighbours are marked dirty so their now-exposed border faces get meshed. */
  removeChunk(cx: number, cz: number): Chunk | undefined {
    const key = chunkKey(cx, cz);
    const chunk = this.chunks.get(key);
    if (!chunk) return undefined;
    this.chunks.delete(key);
    this.getChunk(cx + 1, cz)?.markAllDirty();
    this.getChunk(cx - 1, cz)?.markAllDirty();
    this.getChunk(cx, cz + 1)?.markAllDirty();
    this.getChunk(cx, cz - 1)?.markAllDirty();
    return chunk;
  }

  /** Get-or-create an all-air chunk. */
  ensureChunk(cx: number, cz: number): Chunk {
    let chunk = this.getChunk(cx, cz);
    if (!chunk) {
      chunk = new Chunk(cx, cz);
      this.addChunk(chunk);
    }
    return chunk;
  }

  /** Iterates all loaded chunks. */
  [Symbol.iterator](): IterableIterator<Chunk> {
    return this.chunks.values();
  }

  /** Block at world coordinates; air outside loaded chunks or above the world, stone below it. */
  getBlock(wx: number, wy: number, wz: number): number {
    if (wy < MIN_Y) return BELOW_WORLD;
    if (wy > MAX_Y) return BlockId.Air;
    const chunk = this.getChunk(wx >> 4, wz >> 4);
    return chunk ? chunk.get(wx & 15, wy, wz & 15) : BlockId.Air;
  }

  /** Packed light byte (sky << 4 | block) at world coordinates: open sky above the world and in unloaded chunks, dark below it. */
  getLight(wx: number, wy: number, wz: number): number {
    if (wy < MIN_Y) return 0;
    if (wy > MAX_Y) return OPEN_SKY_LIGHT;
    const chunk = this.getChunk(wx >> 4, wz >> 4);
    return chunk ? chunk.light[blockIndex(wx & 15, wy, wz & 15)]! : OPEN_SKY_LIGHT;
  }

  getSkyLight(wx: number, wy: number, wz: number): number {
    return this.getLight(wx, wy, wz) >> 4;
  }

  getBlockLight(wx: number, wy: number, wz: number): number {
    return this.getLight(wx, wy, wz) & 15;
  }

  /**
   * Sets a block at world coordinates. Returns false if out of range, the chunk isn't loaded, or
   * the block was unchanged. Marks neighbouring sections in adjacent chunks dirty when on a border.
   */
  setBlock(wx: number, wy: number, wz: number, id: number): boolean {
    if (wy < MIN_Y || wy > MAX_Y) return false;
    const cx = wx >> 4;
    const cz = wz >> 4;
    const chunk = this.getChunk(cx, cz);
    if (!chunk) return false;
    const lx = wx & 15;
    const lz = wz & 15;
    if (!chunk.set(lx, wy, lz, id)) return false;
    const sy = sectionOf(wy);
    if (lx === 0) this.getChunk(cx - 1, cz)?.markSectionDirty(sy);
    if (lx === 15) this.getChunk(cx + 1, cz)?.markSectionDirty(sy);
    if (lz === 0) this.getChunk(cx, cz - 1)?.markSectionDirty(sy);
    if (lz === 15) this.getChunk(cx, cz + 1)?.markSectionDirty(sy);
    return true;
  }

  /**
   * Copies section (cx, sy, cz) plus a 1-block border from neighbouring sections/chunks into
   * `out` (length PADDED_VOLUME, see `paddedIndex`). Missing chunks read as air.
   */
  copySectionPadded(cx: number, sy: number, cz: number, out: Uint16Array = new Uint16Array(PADDED_VOLUME)): Uint16Array {
    if (out.length !== PADDED_VOLUME) throw new Error(`copySectionPadded: out must have ${PADDED_VOLUME} entries`);
    // 3x3 neighbourhood of chunks, indexed by (dz + 1) * 3 + (dx + 1).
    const near: (Chunk | undefined)[] = [];
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) near.push(this.getChunk(cx + dx, cz + dz));
    const y0 = sectionBaseY(sy);
    let o = 0;
    for (let py = -1; py <= SECTION_SIZE; py++) {
      const wy = y0 + py;
      const outside = wy < MIN_Y ? BELOW_WORLD : wy > MAX_Y ? BlockId.Air : -1;
      for (let pz = -1; pz <= SECTION_SIZE; pz++) {
        const dz = pz < 0 ? -1 : pz >= SECTION_SIZE ? 1 : 0;
        const lz = pz & 15;
        for (let px = -1; px <= SECTION_SIZE; px++) {
          if (outside >= 0) {
            out[o++] = outside;
            continue;
          }
          const dx = px < 0 ? -1 : px >= SECTION_SIZE ? 1 : 0;
          const chunk = near[(dz + 1) * 3 + (dx + 1)];
          out[o++] = chunk ? chunk.blocks[blockIndex(px & 15, wy, lz)]! : BlockId.Air;
        }
      }
    }
    return out;
  }

  /**
   * Light counterpart of `copySectionPadded`: packed light bytes (sky << 4 | block) for the section
   * plus a 1-block border, in the same `paddedIndex` layout. Above the world and in unloaded chunks
   * reads as open sky; below the world as dark.
   */
  copySectionPaddedLight(cx: number, sy: number, cz: number, out: Uint8Array = new Uint8Array(PADDED_VOLUME)): Uint8Array {
    if (out.length !== PADDED_VOLUME) throw new Error(`copySectionPaddedLight: out must have ${PADDED_VOLUME} entries`);
    const near: (Chunk | undefined)[] = [];
    for (let dz = -1; dz <= 1; dz++) for (let dx = -1; dx <= 1; dx++) near.push(this.getChunk(cx + dx, cz + dz));
    const y0 = sectionBaseY(sy);
    let o = 0;
    for (let py = -1; py <= SECTION_SIZE; py++) {
      const wy = y0 + py;
      const outside = wy < MIN_Y ? 0 : wy > MAX_Y ? OPEN_SKY_LIGHT : -1;
      for (let pz = -1; pz <= SECTION_SIZE; pz++) {
        const dz = pz < 0 ? -1 : pz >= SECTION_SIZE ? 1 : 0;
        const lz = pz & 15;
        for (let px = -1; px <= SECTION_SIZE; px++) {
          if (outside >= 0) {
            out[o++] = outside;
            continue;
          }
          const dx = px < 0 ? -1 : px >= SECTION_SIZE ? 1 : 0;
          const chunk = near[(dz + 1) * 3 + (dx + 1)];
          out[o++] = chunk ? chunk.light[blockIndex(px & 15, wy, lz)]! : OPEN_SKY_LIGHT;
        }
      }
    }
    return out;
  }
}
