import { CHUNK_SIZE, Chunk, MAX_Y } from '../world/chunk';
import { padFromY0, currentBlockPalette } from '../storage/chunkCodec';
import type { ChunkGenerator, GeoBBox } from './generator';

/**
 * Real map worlds (MAP_WORLDS.md phase E): chunks come from mapcore's `MapGen`, compiled to WASM.
 *
 * Shared code stays WASM-agnostic: the client (window and gen workers) and the server load the
 * vendored mapcore build themselves (`@voxel/mapgen/browser` or `/node`) and register it here with
 * `registerMapcore`, before any map generator is created.
 */

/** A mapcore `MapGen` instance (the subset Blockwright uses). */
export interface MapGenHandle {
  generate_chunk(cx: number, cz: number, out: Uint16Array): void;
  spawn(): Int32Array;
  /** [minX, minZ, maxX, maxZ] of the map data, in blocks. */
  area(): Int32Array;
  /** Name labels as a JSON array of `MapLabel` (mapcore package format 3). */
  labels(): string;
  /** y of the top ground block at world (x, z) (package format 4: follows the terrain). */
  ground_at(x: number, z: number): number;
  /** Vertical scale of the terrain: below 1 when mapcore compressed the relief to fit. */
  readonly vertical_scale: number;
  readonly chunk_volume: number;
  free(): void;
}

/** A place name to draw as floating text (street, river, park, building), in world blocks. */
export interface MapLabel {
  text: string;
  kind: 'street' | 'water' | 'park' | 'building';
  x: number;
  y: number;
  z: number;
}

/** The mapcore WASM module's exports. */
export interface MapcoreApi {
  MapGen: new (pkg: Uint8Array, blockNames: string[], chunkHeight?: number) => MapGenHandle;
  /** Flat package (no elevation). */
  prepare(osmJson: string, bbox: Float64Array, scale: number): Uint8Array;
  /** Package with terrain: add every tile `dem_tiles` lists, then `finish()` (milestone 5). */
  MapPrepare: new (osmJson: string, bbox: Float64Array, scale: number, zoom?: number) => MapPrepareHandle;
  /** Elevation tiles an area needs, as flat (z, x, y) triples. */
  dem_tiles(bbox: Float64Array, scale: number, zoom?: number): Uint32Array;
  package_version(): number;
}

/** mapcore's `MapPrepare`. */
export interface MapPrepareHandle {
  add_dem_tile(z: number, x: number, y: number, png: Uint8Array): void;
  finish(): Uint8Array;
  free(): void;
}

/** One Terrarium elevation tile (PNG) used to prepare a package. */
export interface DemTile {
  z: number;
  x: number;
  y: number;
  png: Uint8Array;
}

/**
 * A map world's prepared data and what it was made from (client: IndexedDB `mapPackages` store;
 * server: `map.pkg` + `map.osm.json` in the world folder). The raw OSM JSON is kept so a package
 * from another mapcore format version can be rebuilt instead of the world becoming unplayable.
 */
export interface StoredMapPackage {
  /** The MapPackage (`prepare` output). */
  pkg: Uint8Array;
  /** OpenStreetMap JSON the package was prepared from. */
  osm: string;
  bbox: GeoBBox;
  /** Blocks per metre passed to `prepare`. */
  scale: number;
  /**
   * Elevation tiles the package was prepared with (terrain, mapcore milestone 5); kept so it can be
   * rebuilt offline. Absent or empty: a flat map.
   */
  dem?: DemTile[];
}

let mapcore: MapcoreApi | undefined;

/** Makes the loaded mapcore module available to `createGenerator`. */
export function registerMapcore(api: MapcoreApi): void {
  mapcore = api;
}

export function getMapcore(): MapcoreApi {
  if (!mapcore) throw new Error('mapcore is not loaded (call registerMapcore first)');
  return mapcore;
}

export function isMapcoreRegistered(): boolean {
  return mapcore !== undefined;
}

/**
 * mapcore generates y 0..319 with ground at 64 (Minecraft's numbers), which is exactly Blockwright's
 * world y 0..MAX_Y, so tall towers use the whole height. The layers below y 0 are filled like a
 * padded old chunk (stone, bedrock floor). Saved chunks of older map worlds (generated 0..255) still
 * win over generation.
 */
export const MAPCORE_CHUNK_HEIGHT = MAX_Y + 1;
/** Entries in one mapcore chunk (`MapGen.chunk_volume`). */
export const MAPCORE_CHUNK_VOLUME = CHUNK_SIZE * CHUNK_SIZE * MAPCORE_CHUNK_HEIGHT;

/** Format version stored in a MapPackage header (`MPKG`, then u32 little-endian), or -1 if it is not one. */
export function mapPackageVersion(pkg: Uint8Array): number {
  if (pkg.length < 8 || pkg[0] !== 0x4d || pkg[1] !== 0x50 || pkg[2] !== 0x4b || pkg[3] !== 0x47) return -1;
  return (pkg[4]! | (pkg[5]! << 8) | (pkg[6]! << 16) | (pkg[7]! << 24)) >>> 0;
}

/** `ChunkGenerator` over a mapcore MapPackage. */
export class MapGenerator implements ChunkGenerator {
  readonly kind = 'map' as const;
  private readonly gen: MapGenHandle;
  private readonly buf = new Uint16Array(MAPCORE_CHUNK_VOLUME);
  readonly area: readonly [number, number, number, number];

  constructor(
    api: MapcoreApi,
    pkg: Uint8Array,
    readonly seed = 0,
  ) {
    this.gen = new api.MapGen(pkg, currentBlockPalette(), MAPCORE_CHUNK_HEIGHT);
    if (this.gen.chunk_volume !== MAPCORE_CHUNK_VOLUME) throw new Error(`mapcore chunk volume ${this.gen.chunk_volume}, expected ${MAPCORE_CHUNK_VOLUME}`);
    const a = this.gen.area();
    this.area = [a[0]!, a[1]!, a[2]!, a[3]!];
  }

  /** mapcore's chunk, as it generates it (world y 0..MAX_Y). */
  generateRaw(cx: number, cz: number, out: Uint16Array = new Uint16Array(MAPCORE_CHUNK_VOLUME)): Uint16Array {
    this.gen.generate_chunk(cx, cz, out);
    return out;
  }

  generateChunk(cx: number, cz: number): Chunk {
    this.gen.generate_chunk(cx, cz, this.buf);
    const chunk = new Chunk(cx, cz, padFromY0(this.buf));
    chunk.recount();
    return chunk;
  }

  /** y of the top ground block of a column (mapcore's terrain; buildings and trees not included). */
  surfaceHeight(x: number, z: number): number {
    return this.gen.ground_at(Math.floor(x), Math.floor(z));
  }

  /** Below 1 when mapcore compressed the relief to fit the height (F3). */
  get verticalScale(): number {
    return this.gen.vertical_scale;
  }

  /**
   * Street, water, park and building names from the map (mapcore places them: along named lines
   * about every 150 blocks at ground + 1, at area centres, on roofs). mapcore's y equals world y.
   */
  labels(): MapLabel[] {
    const raw = JSON.parse(this.gen.labels()) as unknown;
    if (!Array.isArray(raw)) return [];
    const out: MapLabel[] = [];
    for (const l of raw as Record<string, unknown>[]) {
      const { text, kind, x, y, z } = l;
      if (typeof text !== 'string' || !text || typeof x !== 'number' || typeof y !== 'number' || typeof z !== 'number') continue;
      out.push({ text, kind: kind === 'water' || kind === 'park' || kind === 'building' ? kind : 'street', x, y, z });
    }
    return out;
  }

  biomeAt(wx: number, wz: number): string {
    const [x0, z0, x1, z1] = this.area;
    return wx >= x0 && wx <= x1 && wz >= z0 && wz <= z1 ? 'map' : 'outside map';
  }

  spawn(): { x: number; y: number; z: number } {
    const s = this.gen.spawn();
    return { x: s[0]!, y: s[1]!, z: s[2]! };
  }

  dispose(): void {
    this.gen.free();
  }
}
